                            <>
                                <img src={ws.cover} alt={ws.title} referrerPolicy="no-referrer" className="absolute inset-0 w-full h-full object-cover scale-95 z-0 transition-transform duration-700 group-hover:scale-100" />
                                <div className="absolute inset-0 bg-linear-to-t from-black/40 via-black/20 to-transparent z-0" />
                            </>
                        )}

                        <div className="flex justify-between items-start relative z-10 w-full">
                            <span className="inline-flex items-center rounded-md bg-background px-2 py-1 text-xs font-medium text-foreground ring-1 ring-inset ring-border">
                                <BookOpen className="mr-1 h-3 w-3" />
                                {ws.author || "N/A"}
                            </span>
                            <Button
                                variant="ghost"
                                size="icon"
                                className="h-6 w-6 text-foreground/70 hover:text-foreground hover:bg-background -mt-1 -mr-1"
                                onClick={(e) => onDelete(e, ws.id)}
                            >
                                <Trash2 className="h-3 w-3" />
                            </Button>
                        </div>
                    </div>

                    <CardContent className="p-5 pt-2 space-y-4 relative z-10 -mt-4">
                        <div>
                            <EditableTitle id={ws.id} initialTitle={ws.title} />
                            <div className="mt-1 flex items-center text-xs text-muted-foreground">
                                <span>Tiếng Trung (中文)</span>
                                <span className="mx-2">→</span>
                                <span>Tiếng Việt</span>
                            </div>
                        </div>

                        <div className="space-y-1.5">
                            <div className="flex justify-between text-xs text-muted-foreground">
                                <span>Tiến độ</span>
                                <span>{stats ? `${stats.translated}/${stats.total} chương` : 'Đang tính...'}</span>
                            </div>
                            <div className="h-1.5 w-full bg-secondary rounded-full overflow-hidden">
                                <div
                                    className="h-full bg-primary transition-all duration-500"
                                    style={{ width: `${progress}%` }}
                                />
                            </div>
                        </div>

                        <div className="flex items-center justify-between pt-2 border-t border-border">
                            <div className="flex items-center text-[10px] text-muted-foreground bg-secondary px-2 py-1 rounded-full">
                                <Clock className="mr-1 h-3 w-3" />
                                {ws.updatedAt?.toLocaleDateString()}
                            </div>
                        </div>
                    </CardContent>
                </Card>
            </div>
        </Link>
    );
};

export function WorkspaceList() {
    const workspaces = useLiveQuery(() => db.workspaces.orderBy("updatedAt").reverse().toArray());
    const [search, setSearch] = useState("");
    const [deleteId, setDeleteId] = useState<string | null>(null);

    useEffect(() => {
        const checkAndRecover = async () => {
            if (workspaces && workspaces.length === 0) {
                await rehydrateFromStorage();
            }
        };
        checkAndRecover();
    }, [workspaces]);

    const handleDeleteConfirm = async () => {
        if (!deleteId) return;
        await db.workspaces.delete(deleteId);
        const chapters = await db.chapters.where("workspaceId").equals(deleteId).primaryKeys();
        await db.chapters.bulkDelete(chapters);
        setDeleteId(null);
    };

    const deleteWorkspace = (e: React.MouseEvent, id: string) => {
        e.preventDefault();
        e.stopPropagation();
        setDeleteId(id);
    }

    const filtered = workspaces?.filter(w => w.title.toLowerCase().includes(search.toLowerCase()));

    if (!workspaces) return <div className="p-10 text-center text-muted-foreground animate-pulse">Đang tải dữ liệu...</div>;

    return (
        <div className="space-y-6">
            <div className="flex justify-between items-center">
                <h2 className="text-xl font-bold text-foreground">My Library</h2>

                <div className="flex items-center gap-2 bg-card p-1.5 pl-4 rounded-full border border-border shadow-lg hover:border-primary/20 transition-all">
                    <div className="relative group w-64">
                        <Search className="absolute left-2 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground group-focus-within:text-foreground transition-colors" />
                        <Input
                            placeholder="Tìm kiếm workspace..."
                            className="pl-8 bg-transparent border-none text-foreground placeholder:text-muted-foreground/60 focus-visible:ring-0 pr-0 h-9"
                            value={search}
                            onChange={(e) => setSearch(e.target.value)}
                        />
                    </div>
                    <div className="h-5 w-px bg-border" />
                    <JSONImportDialog />
                    <div className="h-5 w-px bg-border" />
                    <NewWorkspaceDialog />
                </div>
            </div>

            {workspaces.length === 0 ? (
                <div className="flex flex-col items-center justify-center p-20 border border-dashed rounded-xl border-border bg-card text-center">
                    <div className="h-16 w-16 rounded-full bg-secondary flex items-center justify-center mb-4">
                        <Zap className="h-8 w-8 text-primary" />
                    </div>
                    <p className="text-xl font-bold text-foreground">Chưa có workspace nào</p>
                    <p className="text-muted-foreground mt-2 max-w-sm">
                        Tạo workspace mới để bắt đầu dịch truyện với sức mạnh của AI.
                    </p>
                    <div className="mt-6 flex gap-3">
                        <JSONImportDialog />
                        <NewWorkspaceDialog />
                    </div>
                </div>
            ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
                    {filtered?.map((ws, i) => (
                        <WorkspaceCard key={ws.id} ws={ws} index={i} onDelete={deleteWorkspace} />
                    ))}
                </div>
            )}

            <AlertDialog open={!!deleteId} onOpenChange={(open) => !open && setDeleteId(null)}>
                <AlertDialogContent className="max-w-[400px] rounded-3xl border-rose-100 shadow-2xl">
                    <AlertDialogHeader className="items-center text-center">
                        <div className="h-16 w-16 rounded-full bg-rose-50 flex items-center justify-center mb-2">
                            <AlertTriangle className="h-8 w-8 text-rose-500 animate-bounce" />
                        </div>
                        <AlertDialogTitle className="text-xl font-bold text-slate-900">Xác nhận xóa bộ này?</AlertDialogTitle>
                        <AlertDialogDescription className="text-slate-500">
                            Hành động này sẽ xóa vĩnh viễn toàn bộ chương truyện và dữ liệu liên quan. Bạn không thể hoàn tác.
                        </AlertDialogDescription>
                    </AlertDialogHeader>
                    <AlertDialogFooter className="sm:justify-center gap-2 pt-4">
                        <AlertDialogCancel className="rounded-2xl border-slate-200 text-slate-600 hover:bg-slate-50 px-8">Hủy</AlertDialogCancel>
                        <AlertDialogAction
                            onClick={handleDeleteConfirm}
                            className="rounded-2xl bg-rose-500 hover:bg-rose-600 text-white border-0 px-8 shadow-lg shadow-rose-200"
                        >
                            Xác nhận Xóa
                        </AlertDialogAction>
                    </AlertDialogFooter>
                </AlertDialogContent>
            </AlertDialog>
        </div>
    );
}

