"use client"

import { useState, useEffect } from "react"
import { useLiveQuery } from "dexie-react-hooks"
import { db } from "@/lib/db"
import { Button } from "@/components/ui/button"
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogFooter,
    DialogHeader,
    DialogTitle,
} from "@/components/ui/dialog"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { BookA } from "lucide-react"
import { cn } from "@/lib/utils"

interface DictionaryEditDialogProps {
    workspaceId: string;
    open: boolean;
    onOpenChange: (open: boolean) => void;
    initialOriginal: string;
    initialTranslated?: string; // New prop
    onSaveSuccess: (original: string, translated: string, oldTranslated?: string) => void;
}

export function DictionaryEditDialog({
    workspaceId,
    open,
    onOpenChange,
    initialOriginal,
    initialTranslated = "",
    onSaveSuccess
}: DictionaryEditDialogProps) {
    const [original, setOriginal] = useState(initialOriginal)
    const [translated, setTranslated] = useState(initialTranslated)

    useEffect(() => {
        setOriginal(initialOriginal);
        // If initialTranslated is provided, use it (and clear original if needed, but simple overwrite is safer)
        if (initialTranslated) {
            setTranslated(initialTranslated);

            // Reverse Lookup: If triggered from Translated side (no Original), try to find Original from DB
            if (!initialOriginal && open) {
                db.dictionary.where("translated").equals(initialTranslated).first().then(entry => {
                    if (entry) {
                        setOriginal(entry.original);
                        // Also set "Old Meaning" correctly if we found it in DB
                        // But wait, initialTranslated IS the "Old Meaning" currently in text.
                        // So simple reverse lookup is enough to fill the Key.
                    }
                });
            }

        } else if (initialOriginal && open) {
            // Try to find existing entry only if we are starting from Original
            db.dictionary.where("original").equals(initialOriginal).first().then(entry => {
                if (entry) {
                    setTranslated(entry.translated);
                } else {
                    setTranslated("");
                }
            });
        }
    }, [initialOriginal, initialTranslated, open]);

    const handleSave = async () => {
        if (!translated) return;
        // Validation: Must have Original OR be in "Quick Fix" mode (initialTranslated exists)
        if (!original && !initialTranslated) return;

        try {
            // Priority: Prop > DB
            let oldTranslated = initialTranslated;

            // If we have an Original Key, standard dictionary update
            if (original) {
                const existing = await db.dictionary.where("original").equals(original).first();
                if (existing) {
                    if (!oldTranslated) oldTranslated = existing.translated;
                    await db.dictionary.update(existing.id!, { translated, createdAt: new Date() });
                } else {
                    await db.dictionary.add({
                        workspaceId,
                        original,
                        translated,
                        type: 'term',
                        createdAt: new Date()
                    });
                }
            } else if (initialTranslated) {
                // "Quick Fix" Mode (No Original Key visible)
                // Attempt Reverse Lookup
                const existing = await db.dictionary.where("translated").equals(initialTranslated).first();
                if (existing) {
                    await db.dictionary.update(existing.id!, { translated, createdAt: new Date() });
                    setOriginal(existing.original);
                } else {
                    // Reverse Lookup FAILED -> Create a "Correction Rule" (Viet -> Viet)
                    /*
                       Logic:
                       original = Old Viet (e.g., "Cánh cửa")
                       translated = New Viet (e.g., "Cửa")
                       type = 'correction'
                    */
                    await db.dictionary.add({
                        workspaceId,
                        original: initialTranslated, // Store OLD Viet as Key
                        translated: translated,      // Store NEW Viet as Value
                        type: 'correction',
                        createdAt: new Date()
                    });
                    // Saved correction rule
                }
            }

            onOpenChange(false);
            onSaveSuccess(original || initialTranslated || "", translated, oldTranslated);
        } catch (e) {
            console.error("Failed to save dic entry", e);
            alert("Lỗi khi lưu từ điển");
        }
    }

    return (
        <Dialog open={open} onOpenChange={onOpenChange}>
            <DialogContent className="sm:max-w-[400px] bg-[#1a0b2e] border-white/10 text-white">
                <DialogHeader>
                    <DialogTitle className="flex items-center gap-2">
                        <BookA className="h-5 w-5 text-amber-500" />
                        Sửa Vietphrase
                    </DialogTitle>
                    <DialogDescription className="text-white/50">
                        Thêm hoặc sửa nghĩa của từ/cụm từ.
                    </DialogDescription>
                </DialogHeader>

                <div className="space-y-4 py-4">
                    {/* 
                        Logic: 
                        1. Add Mode (!initialTranslated): ALWAYS show Original Input.
                        2. Edit Mode (initialTranslated): 
                           - Check DB for Original Key (Reverse Lookup).
                           - If FOUND: Hide Original Input (User request).
                           - If NOT FOUND: MUST show Original Input so user can add it (otherwise can't save to Dict).
                    */}
                    {(!initialTranslated || !original) && (
                        <div className="space-y-2 animate-in fade-in slide-in-from-top-2">
                            <Label className="text-white/70">
                                {initialTranslated ? "Nhập Từ gốc (Để lưu vào Từ điển)" : "Từ gốc (Trung)"}
                                <span className="text-red-500">*</span>
                            </Label>
                            <Input
                                value={original}
                                onChange={(e) => setOriginal(e.target.value)}
                                className={cn(
                                    "bg-[#2b2b40] border-white/10 text-white font-lora text-lg",
                                    !original && "ring-1 ring-red-500/50"
                                )}
                                placeholder={initialTranslated ? "Máy không tìm thấy gốc, vui lòng nhập..." : "Nhập/Paste từ gốc Tiếng Trung..."}
                                autoFocus={!original}
                            />
                        </div>
                    )}

                    {initialTranslated && original && (
                        // Hidden Original Key Indicator (Found from DB)
                        <div className="text-xs text-emerald-400 flex items-center gap-1">
                            <span className="opacity-50">Gốc:</span> {original}
                        </div>
                    )}

                    {initialTranslated && (
                        <div className="space-y-2">
                            <Label className="text-white/50 text-xs uppercase">Nghĩa cũ (Hiện tại)</Label>
                            <div className="p-2 rounded bg-white/5 border border-white/10 text-white/60 font-lora line-through decoration-white/30 truncate">
                                {initialTranslated}
                            </div>
                        </div>
                    )}

                    <div className="space-y-2">
                        <Label className="text-white/70">Nghĩa mới (Sửa thành) <span className="text-red-500">*</span></Label>
                        <Input
                            value={translated}
                            onChange={(e) => setTranslated(e.target.value)}
                            className="bg-[#2b2b40] border-white/10 text-white font-lora text-lg focus-visible:ring-amber-500"
                            placeholder="Nhập nghĩa mới..."
                            autoFocus={true} // Always focus here in Quick Fix mode
                            onKeyDown={(e) => e.key === "Enter" && handleSave()}
                        />
                    </div>
                </div>

                <DialogFooter>
                    <div className="flex-1 text-xs text-red-400 flex items-center">
                        {(!original && !initialTranslated) && "Thiếu từ gốc"}
                        {!translated && "Thiếu nghĩa mới"}
                    </div>
                    <Button variant="outline" onClick={() => onOpenChange(false)} className="border-white/10 text-white/70 bg-transparent hover:bg-white/5 hover:text-white">Hủy</Button>
                    <Button
                        onClick={handleSave}
                        className="bg-amber-600 hover:bg-amber-700 text-white"
                        disabled={!translated || (!original && !initialTranslated)}
                    >
                        Lưu {(!original && initialTranslated) ? "(Lưu Quy Tắc Sửa Lỗi)" : "(Enter)"}
                    </Button>
                </DialogFooter>
            </DialogContent>
        </Dialog>
    )
}

"use client"

import React, { useState, useEffect, useRef } from "react"
import { db } from "@/lib/db"
import { settingsRepo } from "@/lib/repositories/settings"
import { checkKeyHealth, parseKeyPool } from "@/lib/services/ai-health"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Textarea } from "@/components/ui/textarea"
import { Key, Database, Sparkles, Loader2, RefreshCw, Settings, XCircle } from "lucide-react"
import { AI_MODELS } from "@/lib/ai-models"
import { cn } from "@/lib/utils"
import {
    Select,
    SelectContent,
    SelectGroup,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select"
import { toast } from "sonner"
import pLimit from "p-limit"

export function AISettingsTab() {
    const [primaryKey, setPrimaryKey] = useState("")
    const [poolKeys, setPoolKeys] = useState("")
    const [model, setModel] = useState("gemini-2.0-flash")
    const [availableModels, setAvailableModels] = useState<{ value: string, label: string }[]>(AI_MODELS)
    const [isLoadingModels, setIsLoadingModels] = useState(false)

    // Key Check State
    const [checkingKeys, setCheckingKeys] = useState(false)
    const [keyStatuses, setKeyStatuses] = useState<{ key: string, status: 'valid' | 'invalid' | 'checking', ms?: number, error?: string }[]>([])

    // Refs for optimization and control
    const lastFetchRef = useRef(0)
    const stopCheckingRef = useRef(false)
    const mountedRef = useRef(true)

    useEffect(() => {
        mountedRef.current = true
        loadSettings()
        return () => { mountedRef.current = false }
    }, [])

    const loadSettings = async () => {
        const [k1, k2, m] = await Promise.all([
            db.settings.get("apiKeyPrimary"),
            db.settings.get("apiKeyPool"),
            db.settings.get("aiModel")
        ])

        if (!mountedRef.current) return

        if (k1) setPrimaryKey(k1.value as string)
        if (k2) setPoolKeys(k2.value as string)
        if (m) setModel(m.value as string)
    }

    const fetchModels = async () => {
        if (!primaryKey) return

        // Anti-spam: Throttle 30s
        const now = Date.now()
        if (now - lastFetchRef.current < 30000) {
            toast.info(`Hãy đợi thêm ${Math.ceil((30000 - (now - lastFetchRef.current)) / 1000)} giây để cập nhật lại.`)
            return
        }

        setIsLoadingModels(true)
        try {
            const response = await fetch(`https://generativelanguage.googleapis.com/v1beta/models?key=${primaryKey}`)
            const data = await response.json()

            if (!mountedRef.current) return

            if (data.models) {
                const models = data.models
                    .map((m: any) => {
                        const id = m.name.replace("models/", "")
                        return { value: id, label: id }
                    })
                    .filter((m: { value: string }) => m.value.includes("gemini"))

                setAvailableModels(models)
                lastFetchRef.current = Date.now()
                toast.success("Đã cập nhật danh sách Model.")
            } else {
                toast.error("Không thể lấy ID model. Kiểm tra lại Key.")
            }
        } catch (e) {
            console.error(e)
            toast.error("Lỗi kết nối khi lấy models.")
        } finally {
            if (mountedRef.current) setIsLoadingModels(false)
        }
    }

    const checkAllKeys = async () => {
        setCheckingKeys(true)
        stopCheckingRef.current = false

        const uniqueKeys = Array.from(new Set([
            primaryKey,
            ...parseKeyPool(poolKeys)
        ])).filter(k => k.length > 5)

        if (uniqueKeys.length === 0) {
            setCheckingKeys(false)
            return
        }

        setKeyStatuses(uniqueKeys.map(k => ({ key: k, status: 'checking' })))

        const limit = pLimit(3)

        const tasks = uniqueKeys.map((key) => limit(async () => {
            if (stopCheckingRef.current) return

            try {
                const { ms } = await checkKeyHealth(key)

                if (!mountedRef.current || stopCheckingRef.current) return

                const result = { key, status: 'valid' as const, ms }
                setKeyStatuses(prev => prev.map(s => s.key === key ? result : s))
                return result
            } catch (e: any) {
                console.warn("Key Check Failed:", e)
                let errorMsg = e.message || e.toString()

                if (e.status === 429 || errorMsg.includes("quota") || errorMsg.includes("RESOURCE_EXHAUSTED")) {
                    errorMsg = "Hết hạn mức (Quota Exceeded)"
                } else if (errorMsg.includes("API key expired")) {
                    errorMsg = "Key đã hết hạn"
                } else if (e.status) {
                    errorMsg = `${e.status} - ${e.statusText || errorMsg}`
                }

                if (!mountedRef.current || stopCheckingRef.current) return

                const result = { key, status: 'invalid' as const, error: errorMsg }
                setKeyStatuses(prev => prev.map(s => s.key === key ? result : s))
                return result
            }
        }))

        await Promise.all(tasks)

        if (mountedRef.current) {
            setCheckingKeys(false)
            if (stopCheckingRef.current) {
                toast.info("Đã dừng kiểm tra key.")
            } else {
                toast.success("Kiểm tra key hoàn tất.")
            }
        }
    }

    const handleSave = async () => {
        try {
            await settingsRepo.saveAISettings(primaryKey, poolKeys, model)
            toast.success("Đã lưu cấu hình AI.")
        } catch (e) {
            console.error("Save failed", e)
            toast.error("Lỗi khi lưu cấu hình.")
        }
    }

    const activeKeyCount = parseKeyPool(poolKeys).length

    return (
        <div className="space-y-4 py-4">
            <div className="space-y-2">
                <Label className="flex items-center gap-2 text-indigo-300 text-xs font-bold uppercase tracking-wider">
                    <Key className="h-4 w-4" /> Primary API Key (Gemini)
                </Label>
                <div className="flex gap-2">
                    <Input
                        type="password"
                        placeholder="AIzaSy..."
                        value={primaryKey}
                        onChange={(e) => setPrimaryKey(e.target.value)}
                        className="bg-[#2b2b40] border-white/10 text-white focus-visible:ring-primary flex-1 h-9 text-sm"
                    />
                    <Button
                        variant="outline"
                        onClick={fetchModels}
                        disabled={!primaryKey || isLoadingModels}
                        className="border-white/10 hover:bg-white/10 h-9 px-3"
                        title="Fetch Available Models"
                    >
                        {isLoadingModels ? <Loader2 className="h-4 w-4 animate-spin text-primary" /> : <RefreshCw className="h-4 w-4" />}
                    </Button>
                </div>
            </div>

            <div className="space-y-2">
                <Label className="flex items-center gap-2 text-indigo-300 text-xs font-bold uppercase tracking-wider">
                    <Database className="h-4 w-4" />
                    Key Pool (Mỗi dòng 1 key)
                    <span className="ml-auto text-[10px] bg-indigo-500/20 px-2 py-0.5 rounded-full text-indigo-300 border border-indigo-500/30">
                        {activeKeyCount} keys active
                    </span>
                </Label>
                <Textarea
                    placeholder={`AIzaSy... (Key 1)\nAIzaSy... (Key 2)`}
                    value={poolKeys}
                    onChange={(e) => setPoolKeys(e.target.value)}
                    className="bg-[#2b2b40] border-white/10 text-white focus-visible:ring-primary font-mono text-xs h-[120px] resize-none"
                />

                <div className="pt-2 flex gap-2">
                    <Button
                        size="sm"
                        variant="secondary"
                        onClick={checkAllKeys}
                        disabled={checkingKeys}
                        className="flex-1 bg-white/5 hover:bg-primary/20 text-indigo-300 border border-indigo-500/30 transition-all h-8 text-[11px] font-bold uppercase tracking-widest"
                    >
                        {checkingKeys ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : <Settings className="mr-2 h-4 w-4" />}
                        {checkingKeys ? "Đang kiểm tra..." : "Kiểm tra tình trạng keys"}
                    </Button>

                    {checkingKeys && (
                        <Button
                            size="sm"
                            variant="ghost"
                            onClick={() => stopCheckingRef.current = true}
                            className="bg-rose-500/10 hover:bg-rose-500/20 text-rose-400 border border-rose-500/30 h-8 px-3"
                            title="Dừng kiểm tra"
                        >
                            <XCircle className="h-4 w-4" />
                        </Button>
                    )}
                </div>

                {keyStatuses.length > 0 && (
                    <div className="mt-2 space-y-1 max-h-[150px] overflow-y-auto p-2 bg-black/40 rounded-lg border border-white/5 custom-scrollbar">
                        {keyStatuses.map((k, i) => (
                            <div key={i} className="flex items-center justify-between text-[11px] px-3 py-1.5 rounded bg-white/5 border border-white/5">
                                <div className="flex items-center gap-2 truncate max-w-[65%]">
                                    <div className={cn("h-2 w-2 rounded-full shrink-0",
                                        k.status === 'valid' ? "bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.5)]" :
                                            k.status === 'invalid' ? "bg-rose-500 shadow-[0_0_8px_rgba(244,63,94,0.5)]" :
                                                "bg-amber-500 animate-pulse"
                                    )} />
                                    <span className="font-mono text-white/60 truncate">{k.key.substring(0, 12)}...{k.key.substring(k.key.length - 6)}</span>
                                </div>
                                <div className="text-right max-w-[35%]">
                                    {k.status === 'valid' ? (
                                        <span className="text-emerald-400 font-mono font-bold tracking-tighter">{k.ms}ms</span>
                                    ) : k.status === 'invalid' ? (
                                        <span className="text-rose-400 text-[9px] break-all block leading-tight font-medium" title={k.error}>{k.error || "Lỗi!"}</span>
                                    ) : (
                                        <span className="text-amber-400 animate-pulse">Checking...</span>
                                    )}
                                </div>
                            </div>
                        ))}
                    </div>
                )}
            </div>

            <div className="space-y-2">
                <Label className="flex items-center gap-2 text-indigo-300 text-xs font-bold uppercase tracking-wider">
                    <Sparkles className="h-4 w-4" /> Default AI Model
                </Label>
                <Select value={model} onValueChange={setModel}>
                    <SelectTrigger className="bg-[#2b2b40] border-white/10 text-white h-9">
                        <SelectValue placeholder="Chọn Model" />
                    </SelectTrigger>
                    <SelectContent className="bg-[#2b2b40] border-white/20 text-white">
                        <SelectGroup>
                            {availableModels.map((m) => (
                                <SelectItem key={m.value} value={m.value} className="focus:bg-primary/20 focus:text-white cursor-pointer hover:bg-white/5">
                                    {m.label}
                                </SelectItem>
                            ))}
                        </SelectGroup>
                    </SelectContent>
                </Select>
            </div>

            <div className="pt-4 border-t border-white/5">
                <Button onClick={handleSave} className="w-full bg-primary hover:bg-primary/90 text-white font-bold h-10 shadow-lg shadow-primary/20">
                    Lưu Cấu Hình AI
                </Button>
            </div>
        </div>
    )
}

"use client"

import React, { useState, useMemo, useEffect } from "react"
import { useLiveQuery } from "dexie-react-hooks"
import { db } from "@/lib/db"
import { dictionaryRepo } from "@/lib/repositories/dictionary"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { ScrollArea } from "@/components/ui/scroll-area"
import { Trash2, Download, Search, Plus, Loader2 } from "lucide-react"
import { toast } from "sonner"

interface DictionaryTabProps {
    workspaceId?: string;
}

// Simple debounce hook
function useDebounce<T>(value: T, delay: number): T {
    const [debouncedValue, setDebouncedValue] = useState<T>(value);
    useEffect(() => {
        const handler = setTimeout(() => setDebouncedValue(value), delay);
        return () => clearTimeout(handler);
    }, [value, delay]);
    return debouncedValue;
}

export function DictionaryTab({ workspaceId }: DictionaryTabProps) {
    const [searchText, setSearchText] = useState("");
    const debouncedSearch = useDebounce(searchText, 300);

    const [newOriginal, setNewOriginal] = useState("");
    const [newTranslated, setNewTranslated] = useState("");
    const [isSaving, setIsSaving] = useState(false);

    // Optimized: Use repository logic within useLiveQuery
    const entries = useLiveQuery(
        () => dictionaryRepo.getByWorkspace(workspaceId),
        [workspaceId],
        []
    );

    // Optimized: Memoize filtering based on debounced search
    const filteredDic = useMemo(() => {
        const query = debouncedSearch.toLowerCase().trim();
        if (!query) return entries;
        return entries.filter(entry =>
            entry.original.toLowerCase().includes(query) ||
            entry.translated.toLowerCase().includes(query)
        );
    }, [entries, debouncedSearch]);

    const handleAddDic = async () => {
        const original = newOriginal.trim();
        const translated = newTranslated.trim();

        if (!original || !translated) return;
        setIsSaving(true);

        let targetWsId = workspaceId;
        if (!targetWsId) {
            const firstWs = await db.workspaces.limit(1).toArray();
            if (firstWs.length > 0) {
                targetWsId = firstWs[0].id;
            }
        }

        if (!targetWsId) {
            toast.error("Không tìm thấy workspace để thêm từ.");
            setIsSaving(false);
            return;
        }

        try {
            await dictionaryRepo.upsert(targetWsId, original, translated);
            toast.success("Đã cập nhật từ điển.");
            setNewOriginal("");
            setNewTranslated("");
        } catch (e) {
            console.error("Failed to add", e);
            toast.error("Lỗi khi lưu từ điển.");
        } finally {
            setIsSaving(false);
        }
    };

    const handleDeleteDic = async (id: number) => {
        try {
            await dictionaryRepo.delete(id);
            toast.success("Đã xóa.");
        } catch (e) {
            toast.error("Lỗi khi xóa.");
        }
    };

    const handleExportDic = async () => {
        if (entries.length === 0) {
            toast.info("Từ điển trống, không có gì để xuất.");
            return;
        }

        const text = entries.map(e => `${e.original}=${e.translated}`).join("\n");
        const blob = new Blob([text], { type: "text/plain;charset=utf-8" });
        const url = URL.createObjectURL(blob);
        const a = document.createElement("a");
        a.href = url;
        a.download = `dictionary-${workspaceId || 'global'}.txt`;
        a.click();
        URL.revokeObjectURL(url);
        toast.success("Đã xuất file từ điển.");
    };

    return (
        <div className="space-y-4 py-4 min-h-[400px]">
            {/* Actions Row */}
            <div className="flex gap-2 items-center">
                <div className="relative flex-1">
                    <Search className="absolute left-2.5 top-2.5 h-4 w-4 text-white/40" />
                    <Input
                        className="pl-9 bg-[#2b2b40] border-white/10 text-white focus-visible:ring-primary h-9 text-xs"
                        placeholder="Tìm kiếm từ..."
                        value={searchText}
                        onChange={(e) => setSearchText(e.target.value)}
                    />
                </div>
                <Button
                    variant="outline"
                    className="border-white/10 text-white/70 hover:bg-white/10 h-9 transition-colors text-xs"
                    onClick={handleExportDic}
                    disabled={entries.length === 0}
                >
                    <Download className="mr-2 h-4 w-4" /> Export Project
                </Button>
            </div>

            {/* Quick Add Row */}
            <div className="grid grid-cols-12 gap-2 items-center p-3 rounded-lg bg-indigo-500/10 border border-indigo-500/20 shadow-inner">
                <div className="col-span-12 sm:col-span-5">
                    <Input
                        placeholder="Từ gốc (Trung)"
                        className="bg-[#1a0b2e] border-white/10 text-white h-9 text-sm font-serif focus-visible:ring-indigo-500"
                        value={newOriginal}
                        onChange={(e) => setNewOriginal(e.target.value)}
                    />
                </div>
                <div className="col-span-12 sm:col-span-5">
                    <Input
                        placeholder="Nghĩa (Việt)"
                        className="bg-[#1a0b2e] border-white/10 text-white h-9 text-sm font-bold focus-visible:ring-indigo-500"
                        value={newTranslated}
                        onChange={(e) => setNewTranslated(e.target.value)}
                        onKeyDown={(e) => e.key === 'Enter' && handleAddDic()}
                    />
                </div>
                <div className="col-span-12 sm:col-span-2">
                    <Button
                        size="sm"
                        className="w-full bg-indigo-600 hover:bg-indigo-700 text-white h-9 shadow-md shadow-indigo-900/20"
                        onClick={handleAddDic}
                        disabled={isSaving || !newOriginal.trim() || !newTranslated.trim()}
                    >
                        {isSaving ? <Loader2 className="h-4 w-4 animate-spin" /> : <><Plus className="h-4 w-4 mr-1" /> Thêm</>}
                    </Button>
                </div>
            </div>

            {/* List Header */}
            <div className="grid grid-cols-12 gap-2 text-[10px] font-bold text-white/40 px-3 uppercase tracking-[0.2em]">
                <div className="col-span-5">Original (CH)</div>
                <div className="col-span-6">Translated (VN)</div>
                <div className="col-span-1 text-right">Act</div>
            </div>

            <ScrollArea className="h-[300px] w-full rounded-md border border-white/10 bg-[#2b2b40]/50 p-1">
                {filteredDic.length === 0 ? (
                    <div className="text-center text-white/30 text-sm italic py-20">
                        {entries.length === 0 ? "Chưa có dữ liệu từ điển" : "Không tìm thấy kết quả"}
                    </div>
                ) : (
                    <div className="divide-y divide-white/5 px-2">
                        {filteredDic.map((entry) => (
                            <div key={entry.id} className="grid grid-cols-12 gap-2 items-center text-sm group hover:bg-white/5 py-2 px-2 rounded transition-all">
                                <div className="col-span-5 text-white font-medium font-serif select-text truncate" title={entry.original}>{entry.original}</div>
                                <div className="col-span-6 text-emerald-400 font-bold select-text truncate" title={entry.translated}>{entry.translated}</div>
                                <div className="col-span-1 text-right">
                                    <Button
                                        variant="ghost"
                                        size="icon"
                                        className="h-6 w-6 text-white/10 hover:text-rose-500 hover:bg-rose-500/10 opacity-0 group-hover:opacity-100 transition-all"
                                        onClick={() => handleDeleteDic(entry.id!)}
                                    >
                                        <Trash2 className="h-3 w-3" />
                                    </Button>
                                </div>
                            </div>
                        ))}
                    </div>
                )}
            </ScrollArea>
        </div>
    );
}

