import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip";
import { AutoResizeTextarea } from "@/components/ui/AutoResizeTextarea";
import {
    Upload, BookOpen, Zap, Users,
    FileText, Database, Sparkles, Loader2,
    Search, Link as LinkIcon
} from "lucide-react";
import { useRaiden } from "@/components/theme/RaidenProvider";
import { useOverview } from "./hooks/useOverview";
import { Workspace } from "@/lib/db";

export const OverviewTab = ({ workspace }: { workspace: Workspace }) => {
    const { isRaidenMode } = useRaiden();
    const fileInputRef = useRef<HTMLInputElement>(null);
    const { state, actions } = useOverview(workspace);

    const { stats, isDragging, isGeneratingSummary } = state;
    const { setIsDragging, handleProcessFile, handleAutoSummary, handleUpdateField } = actions;

    const handleDragOver = (e: React.DragEvent) => {
        e.preventDefault();
        setIsDragging(true);
    };

    const handleDragLeave = (e: React.DragEvent) => {
        e.preventDefault();
        setIsDragging(false);
    };

    const handleDrop = (e: React.DragEvent) => {
        e.preventDefault();
        setIsDragging(false);
        const file = e.dataTransfer.files?.[0];
        if (file && file.type.startsWith('image/')) {
            handleProcessFile(file);
        }
    };

    return (
        <div className="max-w-[1800px] mx-auto px-6 lg:px-8 py-6">
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
                {/* Left Column: Stats & Info */}
                <div className="lg:col-span-1 space-y-6">
                    <Card className={cn(
                        "overflow-hidden relative transition-all",
                        isRaidenMode ? "bg-card border-transparent shadow-2xl" : "bg-card border-border shadow-sm hover:shadow-md"
                    )}>
                        <CardHeader className="pb-2">
                            <CardTitle className={cn("text-base flex items-center gap-2", isRaidenMode ? "text-slate-200" : "text-foreground")}>
                                <Zap className={cn("w-4 h-4", isRaidenMode ? "text-purple-400" : "text-primary")} /> Thống Kê
                            </CardTitle>
                        </CardHeader>
                        <CardContent className="space-y-4">
                            <div className={cn("flex justify-between items-center text-sm p-3 rounded-xl", isRaidenMode ? "bg-slate-900/40" : "bg-muted/30 border border-border/50")}>
                                <span className={isRaidenMode ? "text-slate-400" : "text-muted-foreground font-medium"}>Tổng số chương</span>
                                <span className={cn("font-bold font-mono text-xl", isRaidenMode ? "text-slate-100" : "text-foreground")}>{stats.totalChapters.toLocaleString()}</span>
                            </div>
                            <div className={cn("flex justify-between items-center text-sm p-3 rounded-xl", isRaidenMode ? "bg-slate-900/40" : "bg-muted/30 border border-border/50")}>
                                <span className={isRaidenMode ? "text-slate-400" : "text-muted-foreground font-medium"}>Đã dịch</span>
                                <span className="text-emerald-500 font-bold font-mono text-xl">{stats.translatedChapters.toLocaleString()}</span>
                            </div>
                            <div className="grid grid-cols-2 gap-4">
                                <div className="p-3 rounded-lg bg-background border border-border text-center">
                                    <div className="text-xs text-muted-foreground mb-1">Thuật ngữ</div>
                                    <div className="text-foreground font-bold">{stats.termCount.toLocaleString()}</div>
                                </div>
                                <div className="p-3 rounded-lg bg-background border border-border text-center">
                                    <div className="text-xs text-muted-foreground mb-1">Nhân vật</div>
                                    <div className="text-foreground font-bold">{stats.charCount.toLocaleString()}</div>
                                </div>
                            </div>
                            <div className="pt-2 border-t border-border mt-2">
                                <Tooltip>
                                    <TooltipTrigger className="w-full">
                                        <div className={cn("flex justify-between items-center p-3 rounded-xl cursor-help transition-all hover:scale-[1.02]", isRaidenMode ? "bg-emerald-500/10 border border-emerald-500/20" : "bg-emerald-50/50 border border-emerald-100")}>
                                            <div className={cn("text-xs font-bold uppercase tracking-tight", isRaidenMode ? "text-emerald-400" : "text-emerald-600")}>Translation Cost</div>
                                            <div className="text-right">
                                                <div className={cn("font-black font-mono text-xl leading-tight", isRaidenMode ? "text-emerald-300" : "text-emerald-700")}>${stats.totalCostUSD.toFixed(2)}</div>
                                                <div className="text-[9px] font-medium text-muted-foreground">{stats.translatedChapters} chapters</div>
                                            </div>
                                        </div>
                                    </TooltipTrigger>
                                    <TooltipContent className="text-xs">
                                        <div className="space-y-1">
                                            <div className="font-bold">Cost Breakdown</div>
                                            <div className="grid grid-cols-2 gap-x-3 gap-y-0.5">
                                                <div className="text-muted-foreground">Chapters:</div>
                                                <div className="font-mono">{stats.translatedChapters}</div>

                                                <div className="text-muted-foreground">Total tokens:</div>
                                                <div className="font-mono">{((stats.totalInputTokens + stats.totalOutputTokens) / 1000).toFixed(1)}K</div>

                                                <div className="text-muted-foreground">Avg/chapter:</div>
                                                <div className="font-mono">${(stats.totalCostUSD / Math.max(stats.translatedChapters, 1)).toFixed(4)}</div>
                                            </div>
                                        </div>
                                    </TooltipContent>
                                </Tooltip>
                            </div>
                        </CardContent>
                    </Card>

                    <Card className={cn("overflow-hidden transition-all", isRaidenMode ? "bg-card border-transparent shadow-2xl" : "bg-card border-border shadow-sm")}>
                        <CardHeader className="pb-2">
                            <CardTitle className="text-foreground text-base flex items-center gap-2">
                                <BookOpen className="w-4 h-4 text-primary" /> Thông Tin
                            </CardTitle>
                        </CardHeader>
                        <CardContent className="space-y-6">
                            <div className="space-y-2 group">
                                <label className={cn("text-[10px] uppercase font-bold tracking-widest flex items-center gap-2 transition-colors", isRaidenMode ? "text-slate-500 group-focus-within:text-purple-400" : "text-muted-foreground group-focus-within:text-primary")}>
                                    <Users className="w-3 h-3" /> Tác Giả
                                </label>
                                <input
                                    className={cn("bg-transparent font-bold text-lg w-full border-b focus:ring-0 focus:outline-none placeholder:text-muted-foreground/20 py-2 transition-all", isRaidenMode ? "text-slate-100 border-slate-700 focus:border-purple-500" : "text-foreground border-border focus:border-primary")}
                                    defaultValue={workspace.author?.normalize('NFC')}
                                    placeholder="Chưa rõ tác giả"
                                    onBlur={(e) => handleUpdateField('author', e.target.value.normalize('NFC'))}
                                />
                            </div>
                            <div className="space-y-2 group">
                                <label className={cn("text-[10px] uppercase font-bold tracking-widest flex items-center gap-2 transition-colors", isRaidenMode ? "text-slate-500 group-focus-within:text-purple-400" : "text-muted-foreground group-focus-within:text-primary")}>
                                    <Database className="w-3 h-3" /> Thể Loại
                                </label>
                                <AutoResizeTextarea
                                    className={cn("bg-transparent text-base w-full border-b focus:ring-0 focus:outline-none placeholder:text-muted-foreground/20 py-2 transition-all min-h-[40px] resize-none", isRaidenMode ? "text-slate-200 border-slate-700 focus:border-purple-500" : "text-foreground border-border focus:border-primary")}
                                    defaultValue={workspace.genre?.normalize('NFC') || ""}
                                    placeholder="Chưa phân loại"
                                    onSave={(val) => handleUpdateField('genre', val.normalize('NFC'))}
                                />
                            </div>
                        </CardContent>
                    </Card>
                </div>

                {/* Right Column: Cover & Description */}
                <div className="lg:col-span-2 space-y-6 flex flex-col h-full">
                    <Card
                        className={cn("h-64 flex items-center justify-center relative overflow-hidden group transition-all duration-300", isDragging ? 'border-primary border-2 bg-primary/5' : '', isRaidenMode ? "bg-card border-transparent shadow-2xl" : "bg-card border-border shadow-md")}
                        onDragOver={handleDragOver} onDragLeave={handleDragLeave} onDrop={handleDrop}
                        tabIndex={0}
                        onKeyDown={(e) => {
                            if ((e.ctrlKey || e.metaKey) && e.key === 'v') {
                                navigator.clipboard.readText().then(text => {
                                    if (text.startsWith('http')) handleUpdateField('cover', text);
                                }).catch(() => { });
                            }
                        }}
                    >
                        {workspace.cover ? (
                            <div className="absolute inset-0 w-full h-full">
                                <img
                                    src={workspace.cover}
                                    alt=""
                                    referrerPolicy="no-referrer"
                                    className="absolute inset-0 w-full h-full object-cover blur-2xl opacity-30 scale-110 transition-transform duration-700 group-hover:scale-125"
                                />
                                <div className="absolute inset-0 bg-linear-to-t from-background via-transparent to-transparent opacity-80" />
                                <div className="absolute inset-0 flex items-center justify-center p-6">
                                    <img src={workspace.cover} alt="Cover" referrerPolicy="no-referrer" loading="lazy" className="h-full w-auto object-contain rounded-lg shadow-xl z-10 transition-transform duration-500 group-hover:scale-[1.02]" />
                                </div>
                            </div>
                        ) : (
                            <div className="absolute inset-0 flex flex-col items-center justify-center bg-muted/20 group-hover:bg-muted/40 transition-colors gap-4">
                                <div className="p-4 rounded-full bg-background border border-border group-hover:scale-110 transition-transform duration-300">
                                    <Upload className="h-8 w-8 text-muted-foreground/30 group-hover:text-muted-foreground/60 transition-colors" />
                                </div>
                                <p className="text-muted-foreground/40 text-sm font-medium">Kéo thả hoặc tải ảnh bìa</p>
                                <div className="flex items-center gap-2 mt-2">
                                    <Button
                                        variant="outline"
                                        size="sm"
                                        className="h-7 text-[10px] gap-1.5 bg-background/50 border-dashed hover:bg-background hover:text-primary transition-colors"
                                        onClick={(e) => {
                                            e.stopPropagation();
                                            const query = `${workspace.title} ${workspace.author || ""} novel cover`;
                                            window.open(`https://www.google.com/search?tbm=isch&q=${encodeURIComponent(query)}`, '_blank');
                                        }}
                                    >
                                        <Search className="w-3 h-3" /> Tìm ảnh
                                    </Button>
                                    <Button
                                        variant="outline"
                                        size="sm"
                                        className="h-7 text-[10px] gap-1.5 bg-background/50 border-dashed hover:bg-background hover:text-primary transition-colors"
                                        onClick={async (e) => {
                                            e.stopPropagation();
                                            try {
                                                const text = await navigator.clipboard.readText();
                                                if (text && text.startsWith('http')) {
                                                    handleUpdateField('cover', text);
                                                } else {
                                                    alert("Clipboard không chứa link hợp lệ! Hãy thử copy link ảnh rồi dán lại.");
                                                }
                                            } catch (err) {
                                                console.error("Clipboard read failed:", err);
                                                const manualPaste = prompt("Trình duyệt chặn đọc clipboard tự động. Vui lòng dán link ảnh vào đây:");
                                                if (manualPaste && manualPaste.startsWith('http')) {
                                                    handleUpdateField('cover', manualPaste);
                                                }
                                            }
                                        }}
                                    >
                                        <LinkIcon className="w-3 h-3" /> Dán Link
                                    </Button>
                                </div>
                            </div>
                        )}
                        <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={(e) => e.target.files?.[0] && handleProcessFile(e.target.files[0])} />
                        <div className="absolute bottom-4 right-4 opacity-0 group-hover:opacity-100 transition-all duration-300 translate-y-2 group-hover:translate-y-0 z-40 flex flex-col gap-2">
                            {workspace.cover && (
                                <div className="flex gap-2">
                                    <Button
                                        variant="secondary"
                                        size="icon"
                                        className="h-8 w-8 bg-background/80 text-foreground hover:bg-background border border-border shadow-md rounded-full"
                                        onClick={(e) => {
                                            e.stopPropagation();
                                            const query = `${workspace.title} ${workspace.author || ""} novel cover`;
                                            window.open(`https://www.google.com/search?tbm=isch&q=${encodeURIComponent(query)}`, '_blank');
                                        }}
                                        title="Tìm ảnh khác trên Google"
                                    >
                                        <Search className="h-4 w-4" />
                                    </Button>
                                    <Button
                                        variant="secondary"
                                        size="icon"
                                        className="h-8 w-8 bg-background/80 text-foreground hover:bg-background border border-border shadow-md rounded-full"
                                        onClick={async (e) => {
                                            e.stopPropagation();
                                            try {
                                                const text = await navigator.clipboard.readText();
                                                if (text && text.startsWith('http')) {
                                                    handleUpdateField('cover', text);
                                                } else {
                                                    alert("Clipboard không chứa link hợp lệ! Hãy thử copy link ảnh rồi dán lại.");
                                                }
                                            } catch (err) {
                                                console.error("Clipboard read failed:", err);
                                                // Fallback: Ask user to paste manually
                                                const manualPaste = prompt("Trình duyệt chặn đọc clipboard tự động. Vui lòng dán link ảnh vào đây:");
                                                if (manualPaste && manualPaste.startsWith('http')) {
                                                    handleUpdateField('cover', manualPaste);
                                                }
                                            }
                                        }}
                                        title="Dán link ảnh mới"
                                    >
                                        <LinkIcon className="h-4 w-4" />
                                    </Button>
                                </div>
                            )}

                            <Button variant="secondary" size="sm" className="bg-background/80 text-foreground hover:bg-background border border-border shadow-md" onClick={(e) => { e.stopPropagation(); fileInputRef.current?.click(); }} >
                                <Upload className="h-4 w-4 mr-2" /> {workspace.cover ? "Đổi ảnh" : "Tải ảnh"}
                            </Button>
                        </div>
                    </Card>

                    <Card className={cn("flex-1 flex flex-col overflow-hidden transition-all", isRaidenMode ? "bg-card border-transparent shadow-2xl" : "bg-card border-border shadow-sm")}>
                        <CardHeader className="pb-2">
                            <CardTitle className={cn("text-base flex items-center justify-between", isRaidenMode ? "text-slate-200" : "text-foreground")}>
                                <div className="flex items-center gap-2">
                                    <FileText className={cn("w-4 h-4", isRaidenMode ? "text-purple-400" : "text-primary")} /> Mô Tả / Tóm Tắt
                                    {workspace.isAiDescription && (
                                        <div className={cn("flex items-center gap-1 px-1.5 py-0.5 rounded-md text-[9px] font-black uppercase tracking-tighter shadow-sm", isRaidenMode ? "bg-emerald-500/10 border border-emerald-500/30 text-emerald-400" : "bg-emerald-500/10 border border-emerald-500/20 text-emerald-600")}>
                                            <Sparkles className="w-2.5 h-2.5" /> AI Generated
                                        </div>
                                    )}
                                </div>
                                <Button variant="ghost" size="sm" className={cn("h-7 px-2 transition-all duration-300 rounded-lg group/wand", isRaidenMode ? "text-slate-500 hover:text-purple-400 hover:bg-purple-500/10" : "text-muted-foreground hover:text-primary hover:bg-primary/5", isGeneratingSummary && "animate-pulse")} onClick={handleAutoSummary} disabled={isGeneratingSummary} >
                                    {isGeneratingSummary ? <Loader2 className={cn("w-3.5 h-3.5 animate-spin", isRaidenMode ? "text-purple-400" : "text-primary")} /> : <Sparkles className="w-3.5 h-3.5 group-hover/wand:scale-110 transition-transform" />}
                                </Button>
                            </CardTitle>
                        </CardHeader>
                        <CardContent className="flex-1">
                            <AutoResizeTextarea
                                className={cn("transition-colors", isRaidenMode ? "text-slate-300" : "text-foreground")}
                                defaultValue={workspace.description || ""}
                                placeholder="Nhập mô tả hoặc tóm tắt truyện tại đây..."
                                onSave={(val) => handleUpdateField('description', val)}
                            />
                        </CardContent>
                    </Card>
                </div>
            </div>
        </div>
    );
};

"use client";

import React, { useState, useEffect } from "react";
import { useLiveQuery } from "dexie-react-hooks";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Zap, Swords, Trophy, Sparkles, RefreshCw, Copy, Check, FileText, SparklesIcon, Save, Beaker, Wand2 } from "lucide-react";
import { db } from "@/lib/db";
import { translateChapter, generatePromptVariants, evaluateTranslation, analyzeStyleDNA } from "@/lib/gemini";
import { toast } from "sonner";
import { cn } from "@/lib/utils";
import { useRaiden } from "@/components/theme/RaidenProvider";
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogFooter,
    DialogHeader,
    DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

const SAMPLE_TEXT = `许七安走在京城的街道上，周围是熙熙攘攘的人群。他必须要搞清楚，这个世界到底发生了什么。"天道崩塌，妖魔横行..." 脑海中回荡着这句话。作为一名穿越者，他本想安稳度日，但命运似乎并不打算放过他。前方的打更人衙门威严耸立，那是他唯一的去处。`;

export const PromptLab = ({ workspaceId }: { workspaceId: string }) => {
    const { isRaidenMode } = useRaiden();
    const [testSample, setTestSample] = useState("");
    const [promptGoals, setPromptGoals] = useState("Văn phong trôi chảy, tự nhiên. Giữ nguyên Hán Việt các từ tu tiên.");
    const [promptA, setPromptA] = useState("Mày là dịch giả chuyên nghiệp Trung - Việt. Dịch tự nhiên, giữ nguyên tên riêng.");
    const [promptB, setPromptB] = useState("Dịch văn phong kiếm hiệp, tiên hiệp cổ điển. Dùng nhiều từ Hán Việt sang trọng, trau chuốt.");
    const [isGenerating, setIsGenerating] = useState(false);

    // Fetch first chapter for sample
    const firstChapter = useLiveQuery(() =>
        db.chapters.where("workspaceId").equals(workspaceId).sortBy("order").then(c => c[0]),
        [workspaceId]
    );

    useEffect(() => {
        if (firstChapter?.content_original && !testSample) {
            // Take first 800 chars as sample
            setTestSample(firstChapter.content_original.substring(0, 800) + "...");
        } else if (!firstChapter && !testSample) {
            setTestSample(SAMPLE_TEXT);
        }
    }, [firstChapter, testSample]);

    const [resultA, setResultA] = useState("");
    const [resultB, setResultB] = useState("");
    const [scoreA, setScoreA] = useState<number | null>(null);
    const [scoreB, setScoreB] = useState<number | null>(null);
    const [winner, setWinner] = useState<string | null>(null);
    const [reason, setReason] = useState("");
    const [isFighting, setIsFighting] = useState(false);

    // Save Prompt State
    const [isSaveDialogOpen, setIsSaveDialogOpen] = useState(false);
    const [saveName, setSaveName] = useState("");
    const [pendingSaveContent, setPendingSaveContent] = useState("");

    const openSaveDialog = (defaultName: string, content: string) => {
        setSaveName(defaultName);
        setPendingSaveContent(content);
        setIsSaveDialogOpen(true);
    };

    const confirmSavePrompt = async () => {
        if (!saveName.trim()) {
            toast.error("Vui lòng nhập tên prompt!");
            return;
        }
        await db.prompts.add({
            title: saveName,
            content: pendingSaveContent,
            createdAt: new Date()
        });
        toast.success("Đã lưu prompt vào thư viện!");
        setIsSaveDialogOpen(false);
    };

    const handleGeneratePrompts = async () => {
        if (!promptGoals.trim()) {
            toast.error("Vui lòng nhập mục tiêu prompt!");
            return;
        }
        setIsGenerating(true);
        toast.info("Đang suy nghĩ prompt...");
        try {
            const { promptA, promptB } = await generatePromptVariants(promptGoals);
            setPromptA(promptA);
            setPromptB(promptB);
            toast.success("Đã tạo xong 2 variants!");
        } catch (e: any) {
            toast.error("Lỗi: " + e.message);
        } finally {
            setIsGenerating(false);
        }
    };

    const handleExtractSpirit = async () => {
        setIsGenerating(true);
        toast.info("Đang trích xuất linh hồn (Spirit Extraction)...");
        try {
            // 1. Fetch first 5 chapters
            const chapters = await db.chapters.where("workspaceId").equals(workspaceId).sortBy("order");
            if (chapters.length === 0) {
                throw new Error("Không tìm thấy chương nào để phân tích!");
            }
            const samples = chapters.slice(0, 5).map(c => c.content_original);

            // 2. Analyze DNA
            const dna = await analyzeStyleDNA(samples);

            // 3. Fill Goals
            const newGoals = `Phong cách: ${dna.tone}. Bối cảnh: ${dna.setting}. Xưng hô: ${dna.pronouns}. Mô tả: ${dna.description}`;
            setPromptGoals(newGoals);

            toast.success("Đã trích xuất DNA thành công!", {
                description: dna.tone + " - " + dna.setting
            });

            // Auto generate prompts after extraction? Optional but cool.
            handleGeneratePrompts();

        } catch (e: any) {
            toast.error("Lỗi: " + e.message);
        } finally {
            setIsGenerating(false);
        }
    };


    const handleFight = async () => {
        if (!testSample.trim()) {
            toast.error("Vui lòng nhập văn bản mẫu!");
            return;
        }
        setIsFighting(true);
        setResultA("");
        setResultB("");
        setScoreA(null);
        setScoreB(null);
        setWinner(null);
        setReason("");

        try {
            // 1. Run both translations
            toast.info("Đang bắt đầu so tài...");

            const runA = new Promise<string>((resolve, reject) => {
                translateChapter(workspaceId, testSample, () => { }, (res) => resolve(res.translatedText), promptA)
                    .catch(reject);
            });

            const runB = new Promise<string>((resolve, reject) => {
                translateChapter(workspaceId, testSample, () => { }, (res) => resolve(res.translatedText), promptB)
                    .catch(reject);
            });

            const [resA, resB] = await Promise.all([runA, runB]);
            setResultA(resA);
            setResultB(resB);

            // 2. AI Rating
            toast.info("Trọng tài AI đang chấm điểm...");
            const evalResult = await evaluateTranslation(testSample, resA, resB);

            setScoreA(evalResult.scoreA);
            setScoreB(evalResult.scoreB);
            setWinner(evalResult.winner === "Draw" ? "Hòa" : (evalResult.winner === "A" ? "Prompt A" : "Prompt B"));
            setReason(evalResult.reason);

        } catch (e: any) {
            toast.error("Lỗi khi chạy Test: " + e.message);
        } finally {
            setIsFighting(false);
        }
    };

    return (
        <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
            <div className="flex items-center justify-between">
                <div>
                    <h2 className="text-2xl font-black text-foreground tracking-tight flex items-center gap-2">
                        <Swords className="w-6 h-6 text-primary" />
                        Prompt Lab
                    </h2>
                    <p className="text-muted-foreground text-sm">Thử nghiệm và tối ưu hóa câu lệnh dịch (A/B Testing)</p>
                </div>
                <Button
                    onClick={handleFight}
                    disabled={isFighting}
                    className="bg-primary hover:bg-primary/90 text-white font-black px-10 py-7 rounded-2xl shadow-xl shadow-primary/20 gap-3 group overflow-hidden relative active:scale-95 transition-all"
                >
                    <div className="absolute inset-0 bg-white/10 translate-y-full group-hover:translate-y-0 transition-transform duration-300" />
                    <RefreshCw className={cn("w-5 h-5", isFighting && "animate-spin")} />
                    {isFighting ? "ĐANG CHIẾN ĐẤU..." : "START A/B TEST"}
                </Button>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                {/* Left: Input & Generator */}
                <Card className={cn("border-border shadow-sm", isRaidenMode ? "bg-card border-transparent" : "bg-card")}>
                    <CardHeader className={cn("pb-3 border-b border-l-4 border-l-indigo-500", !isRaidenMode && "bg-muted/30")}>
                        <CardTitle className="text-foreground text-sm font-bold flex items-center justify-between gap-2">
                            <div className="flex items-center gap-2">
                                <FileText className="w-4 h-4 text-indigo-500" />
                                VĂN BẢN MẪU (TEST SAMPLE)
                            </div>
                            <Button
                                variant="outline"
                                size="sm"
                                onClick={() => {
                                    if (firstChapter?.content_original) {
                                        setTestSample(firstChapter.content_original.substring(0, 800) + "...");
                                        toast.success("Đã lấy nội dung gốc từ Chương 1!");
                                    } else {
                                        setTestSample(SAMPLE_TEXT);
                                        toast.info("Không tìm thấy chương nào, dùng văn bản mẫu.");
                                    }
                                }}
                                className="text-[10px] bg-white border-slate-200 text-slate-600 hover:text-primary h-6 px-2"
                            >
                                <RefreshCw className="w-2.5 h-2.5 mr-1" />
                                Reset
                            </Button>
                        </CardTitle>
                    </CardHeader>
                    <CardContent className="pt-4">
                        <Textarea
                            value={testSample}
                            onChange={(e) => setTestSample(e.target.value)}
                            className="bg-slate-50/30 border-border text-foreground text-sm h-36 focus:bg-white transition-all resize-none font-sans"
                            placeholder="Nhập đoạn văn bản muốn test dịch..."
                        />
                    </CardContent>
                </Card>

                <Card className={cn("border-border shadow-sm", isRaidenMode ? "bg-card border-transparent" : "bg-card")}>
                    <CardHeader className={cn("pb-3 border-b border-l-4 border-l-primary", !isRaidenMode && "bg-muted/30")}>
                        <CardTitle className="text-foreground text-sm font-bold flex items-center gap-2">
                            <Zap className="w-4 h-4 text-primary" />
                            MỤC TIÊU CẦN ĐẠT
                        </CardTitle>
                    </CardHeader>
                    <CardContent className="pt-4 space-y-4">
                        <p className="text-[11px] text-muted-foreground italic">
                            * Nhập phong cách bạn muốn (VD: Kiếm hiệp, Hiện đại...) AI sẽ tối ưu prompt.
                        </p>
                        <Textarea
                            value={promptGoals}
                            onChange={(e) => setPromptGoals(e.target.value)}
                            className="bg-slate-50/30 border-border text-foreground text-sm h-16 focus:bg-white transition-all resize-none font-sans"
                            placeholder="Mô tả mục tiêu..."
                        />
                        <div className="flex gap-2">
                            <Button
                                disabled={isGenerating}
                                onClick={handleExtractSpirit}
                                variant="outline"
                                className="flex-1 bg-indigo-50 text-indigo-600 border-indigo-200 hover:bg-indigo-100 h-9 text-xs font-bold"
                            >
                                <Wand2 className={cn("w-3.5 h-3.5 mr-1.5", isGenerating && "animate-spin")} />
                                Spirit DNA
                            </Button>
                            <Button
                                disabled={isGenerating}
                                onClick={handleGeneratePrompts}
                                className="flex-1 h-9 text-xs font-bold"
                            >
                                <SparklesIcon className={cn("w-3.5 h-3.5 mr-1.5", isGenerating && "animate-spin")} />
                                Tạo Prompt
                            </Button>
                        </div>
