import { toast } from "sonner";
import { db } from "@/lib/db";
import { translateChapter, generatePromptVariants, evaluateTranslation, analyzeStyleDNA } from "@/lib/gemini";

interface UsePromptActionsProps {
  workspaceId: string;
  promptGoals: string;
  setPromptA: (value: string) => void;
  setPromptB: (value: string) => void;
  setPromptGoals: (value: string) => void;
  testSample: string;
  promptA: string;
  promptB: string;
  setResultA: (value: string) => void;
  setResultB: (value: string) => void;
  setScoreA: (value: number | null) => void;
  setScoreB: (value: number | null) => void;
  setWinner: (value: string | null) => void;
  setReason: (value: string) => void;
  saveName: string;
  pendingSaveContent: string;
  setIsSaveDialogOpen: (value: boolean) => void;
  setSaveName: (value: string) => void;
  setPendingSaveContent: (value: string) => void;
}

export function usePromptActions(props: UsePromptActionsProps) {
  const {
    workspaceId,
    promptGoals,
    setPromptA,
    setPromptB,
    setPromptGoals,
    testSample,
    promptA,
    promptB,
    setResultA,
    setResultB,
    setScoreA,
    setScoreB,
    setWinner,
    setReason,
    saveName,
    pendingSaveContent,
    setIsSaveDialogOpen,
    setSaveName,
    setPendingSaveContent,
  } = props;

  const openSaveDialog = (defaultName: string, content: string) => {
    setSaveName(defaultName);
    setPendingSaveContent(content);
    setIsSaveDialogOpen(true);
  };

  const confirmSavePrompt = async () => {
    if (!saveName.trim()) {
      toast.error("Vui lòng nhập tên prompt!");
      return;
    }
    await db.prompts.add({
      title: saveName,
      content: pendingSaveContent,
      createdAt: new Date()
    });
    toast.success("Đã lưu prompt vào thư viện!");
    setIsSaveDialogOpen(false);
  };

  const handleGeneratePrompts = async () => {
    if (!promptGoals.trim()) {
      toast.error("Vui lòng nhập mục tiêu prompt!");
      return false;
    }
    toast.info("Đang suy nghĩ prompt...");
    try {
      const { promptA, promptB } = await generatePromptVariants(promptGoals);
      setPromptA(promptA);
      setPromptB(promptB);
      toast.success("Đã tạo xong 2 variants!");
      return true;
    } catch (e: any) {
      toast.error("Lỗi: " + e.message);
      return false;
    }
  };

  const handleExtractSpirit = async () => {
    toast.info("Đang trích xuất linh hồn (Spirit Extraction)...");
    try {
      const chapters = await db.chapters.where("workspaceId").equals(workspaceId).sortBy("order");
      if (chapters.length === 0) {
        throw new Error("Không tìm thấy chương nào để phân tích!");
      }
      const samples = chapters.slice(0, 5).map(c => c.content_original);
      const dna = await analyzeStyleDNA(samples);
      const newGoals = `Phong cách: ${dna.tone}. Bối cảnh: ${dna.setting}. Xưng hô: ${dna.pronouns}. Mô tả: ${dna.description}`;
      setPromptGoals(newGoals);
      toast.success("Đã trích xuất DNA thành công!", {
        description: dna.tone + " - " + dna.setting
      });
      await handleGeneratePrompts();
      return true;
    } catch (e: any) {
      toast.error("Lỗi: " + e.message);
      return false;
    }
  };

  const handleFight = async () => {
    if (!testSample.trim()) {
      toast.error("Vui lòng nhập văn bản mẫu!");
      return false;
    }

    setResultA("");
    setResultB("");
    setScoreA(null);
    setScoreB(null);
    setWinner(null);
    setReason("");

    try {
      toast.info("Đang bắt đầu so tài...");

      const runA = new Promise<string>((resolve, reject) => {
        translateChapter(workspaceId, testSample, () => { }, (res) => resolve(res.translatedText), promptA)
          .catch(reject);
      });

      const runB = new Promise<string>((resolve, reject) => {
        translateChapter(workspaceId, testSample, () => { }, (res) => resolve(res.translatedText), promptB)
          .catch(reject);
      });

      const [resA, resB] = await Promise.all([runA, runB]);
      setResultA(resA);
      setResultB(resB);

      toast.info("Trọng tài AI đang chấm điểm...");
      const evalResult = await evaluateTranslation(testSample, resA, resB);

      setScoreA(evalResult.scoreA);
      setScoreB(evalResult.scoreB);
      setWinner(evalResult.winner === "Draw" ? "Hòa" : (evalResult.winner === "A" ? "Prompt A" : "Prompt B"));
      setReason(evalResult.reason);

      return true;
    } catch (e: any) {
      toast.error("Lỗi khi chạy Test: " + e.message);
      return false;
    }
  };

  return {
    openSaveDialog,
    confirmSavePrompt,
    handleGeneratePrompts,
    handleExtractSpirit,
    handleFight,
  };
}

"use client";

import React from "react";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import {
    BookOpen, Zap, ShieldCheck, AlertCircle, Clock, Eraser
} from "lucide-react";
import { cn } from "@/lib/utils";
import { format } from "date-fns";
import { vi } from "date-fns/locale";
import { useRaiden } from "@/components/theme/RaidenProvider";

// Inline Badge component
const Badge = ({ children, className }: { children: React.ReactNode; className?: string }) => (
    <span className={cn("inline-flex items-center rounded-md px-2 py-0.5 text-xs font-medium border", className)}>
        {children}
    </span>
);

interface ChapterCardProps {
    id: number;
    order: number;
    title: string;
    title_translated?: string;
    status: 'draft' | 'translated' | 'reviewing';
    issueCount: number;
    lastTranslatedAtTime?: number;
    translationDurationMs?: number;
    wordCountOriginal?: number;
    isSelected: boolean;
    isLastRead: boolean;
    hasContent: boolean;
    hasTitle: boolean;

    // Handlers
    onSelect: (checked: boolean, shiftKey?: boolean) => void;
    onRead: () => void;
    onTranslate: () => void;
    onInspect: () => void;
    onClearTranslation: () => void;
    onDelete: () => void;
    onContextMenu?: (e: React.MouseEvent) => void;
    onMouseEnter?: () => void;
}

export const ChapterCard = React.memo(function ChapterCard({
    id,
    order,
    title,
    title_translated,
    status,
    issueCount,
    lastTranslatedAtTime,
    wordCountOriginal,
    isSelected,
    isLastRead,
    hasContent,
    hasTitle,
    onSelect,
    onRead,
    onTranslate,
    onInspect,
    onClearTranslation,
    onContextMenu,
    onMouseEnter
}: ChapterCardProps) {
    const { isRaidenMode } = useRaiden();

    const isTranslated = status === 'translated' || hasContent || hasTitle;

    return (
        <div
            className={cn(
                "group relative p-4 rounded-2xl border transition-all duration-300",
                isRaidenMode ? "bg-slate-900/50" : "bg-card",
                isSelected
                    ? (isRaidenMode ? "border-purple-500 bg-purple-900/20 shadow-[0_0_20px_rgba(168,85,247,0.1)]" : "border-blue-300 bg-blue-50/80 shadow-md scale-[1.01]")
                    : (isRaidenMode ? "border-slate-800 hover:border-slate-700 hover:bg-slate-800/40" : "border-slate-100 hover:bg-white hover:border-blue-200 hover:shadow-lg"),
                isLastRead && (isRaidenMode ? "ring-2 ring-emerald-500/50 shadow-[0_0_15px_rgba(16,185,129,0.2)]" : "ring-2 ring-emerald-500/30 border-emerald-400/50 shadow-[0_0_15px_rgba(16,185,129,0.1)]")
            )}
            onContextMenu={onContextMenu}
            onMouseEnter={onMouseEnter}
            onClick={(e) => {
                // If modifier is held, toggle selection instead of reading
                if (e.ctrlKey || e.metaKey || e.altKey || e.shiftKey) {
                    onSelect(!isSelected, e.shiftKey);
                    return;
                }
                onRead();
            }}
        >
            {/* Last Read Pulse */}
            {isLastRead && (
                <div className="absolute -top-1.5 -right-1.5 z-10 flex">
                    <span className="relative flex h-3 w-3">
                        <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-75"></span>
                        <span className="relative inline-flex rounded-full h-3 w-3 bg-emerald-500"></span>
                    </span>
                </div>
            )}

            <div className="flex items-start justify-between gap-3 mb-3">
                <div className="flex items-start gap-3 flex-1 min-w-0">
                    <Checkbox
                        checked={isSelected}
                        onCheckedChange={(checked) => onSelect(!!checked, (window.event as MouseEvent)?.shiftKey)}
                        className={cn(
                            "mt-1 rounded-md transition-all",
                            isRaidenMode ? "border-slate-700 data-[state=checked]:bg-purple-600" : "border-slate-200 data-[state=checked]:bg-blue-600"
                        )}
                    />
                    <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2 mb-0.5 group/title">
                            <span className={cn(
                                "text-[10px] font-mono px-1.5 py-0.5 rounded-md",
                                isRaidenMode ? "bg-slate-800 text-slate-500" : "bg-slate-100 text-slate-400"
                            )}>
                                #{order}
                            </span>
                            <h3 className={cn(
                                "font-bold text-sm truncate font-serif transition-colors",
                                isRaidenMode ? "text-slate-200 group-hover/title:text-purple-400" : "text-slate-900 group-hover/title:text-blue-600"
                            )}>
                                {title.replace(/<br\s*\/?>/gi, " ")}
                            </h3>
                        </div>
                        <p className={cn(
                            "text-xs truncate italic",
                            isRaidenMode ? "text-slate-500" : "text-slate-500"
                        )}>
                            {(title_translated || "Chưa dịch tiêu đề...").replace(/<br\s*\/?>/gi, " ")}
                        </p>
                    </div>
                </div>

                <Button
                    size="icon"
                    variant="ghost"
                    onClick={onRead}
                    className={cn(
                        "h-8 w-8 rounded-full opacity-0 group-hover:opacity-100 transition-all",
                        isRaidenMode ? "hover:bg-purple-500/20 text-purple-400" : "hover:bg-blue-50 text-blue-600"
                    )}
                >
                    <BookOpen className="h-4 w-4" />
                </Button>
            </div>

            {/* Progress Visualization */}
            <div className="space-y-2 mb-3">
                <div className="flex items-center justify-between text-[10px] font-bold uppercase tracking-wider">
                    <Badge className={cn(
                        "px-2 py-0.5 rounded-full border-0 gap-1.5",
                        isTranslated
                            ? (isRaidenMode ? "bg-emerald-500/10 text-emerald-400" : "bg-emerald-50 text-emerald-600")
                            : (isRaidenMode ? "bg-slate-800 text-slate-500" : "bg-slate-100 text-slate-400")
                    )}>
                        <div className={cn(
                            "w-1.5 h-1.5 rounded-full",
                            isTranslated ? "bg-emerald-500 animate-pulse" : "bg-slate-400"
                        )} />
                        {isTranslated ? "Đã hoàn thành" : "Bản thảo"}
                    </Badge>
                    <span className="text-muted-foreground/40">{wordCountOriginal?.toLocaleString() || 0} chữ</span>
                </div>
                <div className={cn(
                    "h-1.5 w-full rounded-full overflow-hidden",
                    isRaidenMode ? "bg-slate-800" : "bg-slate-100"
                )}>
                    <div
                        className={cn(
                            "h-full transition-all duration-1000 ease-out",
                            isTranslated
                                ? "w-full bg-linear-to-r from-emerald-500 to-emerald-400"
                                : "w-[15%] bg-slate-400/30"
                        )}
                    />
                </div>
            </div>

            <div className="flex items-center justify-between">
                <div className="flex items-center gap-1.5">
                    {issueCount > 0 && (
                        <div className="flex items-center gap-1 text-[9px] font-black text-rose-500 bg-rose-500/10 px-1.5 py-0.5 rounded-md animate-pulse">
                            <AlertCircle className="h-2.5 w-2.5" />
                            {issueCount} LỖI
                        </div>
                    )}
                    {lastTranslatedAtTime && (
                        <div className="flex items-center gap-1 text-[9px] text-muted-foreground/50">
                            <Clock className="h-2.5 w-2.5" />
                            {format(new Date(lastTranslatedAtTime), "HH:mm", { locale: vi })}
                        </div>
                    )}
                </div>

                {/* Hover Actions */}
                <div className="flex items-center gap-0.5 opacity-0 group-hover:opacity-100 transition-all translate-y-1 group-hover:translate-y-0">
                    <Button
                        size="icon"
                        variant="ghost"
                        onClick={onTranslate}
                        className="h-7 w-7 rounded-lg hover:bg-primary/10 text-primary"
                        title="Dịch chương"
                    >
                        <Zap className="h-3.5 w-3.5" />
                    </Button>
                    <Button
                        size="icon"
                        variant="ghost"
                        onClick={onInspect}
                        className="h-7 w-7 rounded-lg hover:bg-amber-500/10 text-amber-500"
                        title="Soi lỗi"
                    >
                        <ShieldCheck className="h-3.5 w-3.5" />
                    </Button>
                    <Button
                        size="icon"
                        variant="ghost"
                        onClick={onClearTranslation}
                        className="h-7 w-7 rounded-lg hover:bg-rose-500/10 text-rose-500"
                        title="Reset bản dịch"
                    >
                        <Eraser className="h-3.5 w-3.5" />
                    </Button>
                </div>
            </div>
        </div>
    );
});

ChapterCard.displayName = "ChapterCard";

"use client";

import React, { useRef } from "react";
import { ChapterCard } from "./ChapterCard";
import { FileUp } from "lucide-react";
import { db, type Chapter } from "@/lib/db";
import { type AiQueueState } from "@/lib/services/ai-queue";
import { Button } from "@/components/ui/button";
import { useVirtualizer } from "@tanstack/react-virtual";
import {
    AlertDialog,
    AlertDialogAction,
    AlertDialogCancel,
    AlertDialogContent,
    AlertDialogDescription,
    AlertDialogFooter,
    AlertDialogHeader,
    AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { AlertTriangle } from "lucide-react";

interface ChapterCardGridProps {
    chapters: Chapter[];
    selectedChapters: number[];
    queueState: AiQueueState; // Not used in grid view, but required for consistency
    onSelect: (id: number, shiftKey?: boolean) => void;
    onRead: (id: number) => void;
    onInspect: (id: number) => void;
    onClearTranslation: (id: number) => void;
    onImport?: () => void;
    lastReadChapterId?: number;
}

export const ChapterCardGrid = React.memo(function ChapterCardGrid({
    chapters,
    selectedChapters,
    onSelect,
    onRead,
    onInspect,
    onClearTranslation,
    onImport,
    lastReadChapterId
}: ChapterCardGridProps) {
    const [deleteId, setDeleteId] = React.useState<number | null>(null);
    const parentRef = useRef<HTMLDivElement>(null);

    const rowVirtualizer = useVirtualizer({
        count: chapters.length,
        getScrollElement: () => parentRef.current,
        estimateSize: () => 110, // Cards are roughly this height
        overscan: 5,
    });

    const selectedSet = React.useMemo(() => new Set(selectedChapters), [selectedChapters]);

    if (chapters.length === 0) {
        return (
            <div className="bg-card rounded-xl border border-border shadow-lg p-8">
                <div className="flex flex-col items-center justify-center min-h-[400px] text-center space-y-6">
                    <div className="p-6 rounded-3xl bg-muted/50 border border-border shadow-inner">
                        <FileUp className="h-16 w-16 text-muted-foreground/20 animate-pulse" />
                    </div>
                    <div className="space-y-2">
                        <p className="text-xl font-bold text-foreground">Chưa có chương nào</p>
                        <p className="text-sm text-muted-foreground/60 max-w-sm leading-relaxed">
                            Tải lên file EPUB hoặc TXT để bắt đầu dịch truyện của bạn ngay bây giờ.
                        </p>
                    </div>
                    {onImport && (
                        <Button
                            onClick={onImport}
                            className="bg-primary hover:bg-primary/90 text-primary-foreground px-8 h-12 rounded-2xl font-bold shadow-lg shadow-primary/20 transition-all hover:scale-105 active:scale-95 gap-2"
                        >
                            <FileUp className="w-5 h-5" />
                            Tải lên ngay
                        </Button>
                    )}
                </div>
            </div>
        );
    }

    return (
        <div className="bg-card rounded-xl border border-border shadow-lg p-2 h-[70vh] flex flex-col overflow-hidden">
            <div
                ref={parentRef}
                className="flex-1 overflow-auto custom-scrollbar relative p-2"
            >
                <div
                    style={{
                        height: `${rowVirtualizer.getTotalSize()}px`,
                        width: '100%',
                        position: 'relative',
                    }}
                >
                    {rowVirtualizer.getVirtualItems().map((virtualRow) => {
                        const chapter = chapters[virtualRow.index];
                        return (
                            <div
                                key={virtualRow.key}
                                style={{
                                    position: 'absolute',
                                    top: 0,
                                    left: 0,
                                    width: '100%',
                                    height: `${virtualRow.size}px`,
                                    transform: `translateY(${virtualRow.start}px)`,
                                    paddingBottom: '8px' // Gap replacement
                                }}
                            >
                                <ChapterCard
                                    id={chapter.id!}
                                    order={chapter.order}
                                    title={chapter.title}
                                    title_translated={chapter.title_translated}
                                    status={chapter.status || 'draft'}
                                    issueCount={chapter.inspectionResults?.length || 0}
                                    lastTranslatedAtTime={chapter.lastTranslatedAt instanceof Date ? chapter.lastTranslatedAt.getTime() : (chapter.lastTranslatedAt ? new Date(chapter.lastTranslatedAt).getTime() : undefined)}
                                    translationDurationMs={chapter.translationDurationMs}
                                    wordCountOriginal={chapter.wordCountOriginal}
                                    isSelected={selectedSet.has(chapter.id!)}
                                    isLastRead={lastReadChapterId === chapter.id}
                                    hasContent={!!chapter.content_translated && chapter.content_translated.length > 0}
                                    hasTitle={!!chapter.title_translated && chapter.title_translated.length > 0}
                                    onSelect={(checked, shiftKey) => onSelect(chapter.id!, shiftKey)}
                                    onRead={() => onRead(chapter.id!)}
                                    onTranslate={() => {/* Unified batch handler preferred */ }}
                                    onInspect={() => onInspect(chapter.id!)}
                                    onClearTranslation={() => onClearTranslation(chapter.id!)}
                                    onDelete={() => setDeleteId(chapter.id!)}
                                />
                            </div>
                        );
                    })}
                </div>
            </div>

            <AlertDialog open={!!deleteId} onOpenChange={(open) => !open && setDeleteId(null)}>
                <AlertDialogContent className="max-w-[400px] rounded-3xl border-rose-100 shadow-2xl">
                    <AlertDialogHeader className="items-center text-center">
                        <div className="h-16 w-16 rounded-full bg-rose-50 flex items-center justify-center mb-2">
                            <AlertTriangle className="h-8 w-8 text-rose-500 animate-bounce" />
                        </div>
                        <AlertDialogTitle className="text-xl font-bold text-slate-900">Xác nhận xóa chương?</AlertDialogTitle>
                        <AlertDialogDescription className="text-slate-500">
                            Bạn sắp xóa vĩnh viễn chương truyện này khỏi thư viện. Hành động này không thể hoàn tác.
                        </AlertDialogDescription>
                    </AlertDialogHeader>
                    <AlertDialogFooter className="sm:justify-center gap-2 pt-4">
                        <AlertDialogCancel className="rounded-2xl border-slate-200 text-slate-600 hover:bg-slate-50 px-8">Hủy</AlertDialogCancel>
                        <AlertDialogAction
                            onClick={async () => {
                                if (deleteId) {
                                    await db.chapters.delete(deleteId);
                                    setDeleteId(null);
                                }
                            }}
                            className="rounded-2xl bg-rose-500 hover:bg-rose-600 text-white border-0 px-8 shadow-lg shadow-rose-200"
                        >
                            Xác nhận Xóa
                        </AlertDialogAction>
                    </AlertDialogFooter>
                </AlertDialogContent>
            </AlertDialog>
        </div>
    );
});

ChapterCardGrid.displayName = "ChapterCardGrid";

"use client";

import React, { useState, useMemo, useEffect } from "react";
import { useLiveQuery } from "dexie-react-hooks";
import Dexie from "dexie";
import { toast } from "sonner";

import { db, type Chapter } from "@/lib/db";
import { ReviewData, GlossaryCharacter, GlossaryTerm, TranslationSettings } from "@/lib/types";

import { usePersistedState } from "@/lib/hooks/usePersistedState";
import { useChapterSelection } from "../hooks/useChapterSelection";
import { useChapterImport } from "../hooks/useChapterImport";
import { useAIExtraction } from "../editor/hooks/useAIExtraction";
import { useAiQueueStats } from "../hooks/useAiQueueStatus";

import { useChapterActions } from "./hooks/useChapterActions";
import { useCorrections } from "./hooks/useCorrections";
import { useDialogStates } from "./hooks/useDialogStates";
import { useScanConfig } from "./hooks/useScanConfig";
import { useReaderNavigation } from "./hooks/useReaderNavigation";

import { ChapterListHeader } from "../shared/ChapterListHeader";
import { ImportProgressOverlay } from "./ImportProgressOverlay";
import { ChapterSelectionDock } from "../ChapterSelectionDock";
import { ChapterListDialogs } from "./components/ChapterListDialogs";
import { ChapterListContent } from "./components/ChapterListContent";

interface ChapterListProps {
    workspaceId: string;
    onShowScanResults: (data: ReviewData) => void;
    onTranslate: (props: {
        workspaceId: string;
        chapters: Chapter[];
        selectedChapters: number[];
        currentSettings: TranslationSettings;
        translateConfig: {
            customPrompt: string;
            autoExtract: boolean;
            fixPunctuation?: boolean;
            maxConcurrency?: number;
            enableChunking: boolean;
            maxConcurrentChunks: number;
            chunkSize?: number;
        };
        onReviewNeeded: (chars: GlossaryCharacter[], terms: GlossaryTerm[]) => void;
    }) => void;
}

export function ChapterList({ workspaceId, onShowScanResults, onTranslate }: ChapterListProps) {
    const workspace = useLiveQuery(() => db.workspaces.get(workspaceId), [workspaceId]);
    const chapters = useLiveQuery(
        () => db.chapters.where("[workspaceId+order]").between([workspaceId, Dexie.minKey], [workspaceId, Dexie.maxKey]).toArray(),
        [workspaceId]
    );

    const [search, setSearch] = useState("");
    const [filterStatus, setFilterStatus] = usePersistedState<"all" | "draft" | "translated">(`workspace-${workspaceId}-filter`, "all");
    const [currentPage, setCurrentPage] = useState(1);
    const [itemsPerPage, setItemsPerPage] = usePersistedState(`workspace-${workspaceId}-perPage`, 50);
    const [viewMode, setViewMode] = usePersistedState<"grid" | "table">(`workspace-${workspaceId}-viewMode`, "grid");

    const filtered = useMemo(() => {
        if (!chapters) return [];
        return chapters.filter(c => {
            const matchesSearch = c.title.toLowerCase().includes(search.toLowerCase());
            const matchesStatus = filterStatus === "all" || c.status === filterStatus;
            return matchesSearch && matchesStatus;
        });
    }, [chapters, search, filterStatus]);

    const allChapterIds = useMemo(() => filtered.map(c => c.id!), [filtered]);

    const {
        selectedChapters,
        setSelectedChapters,
        handleSelect
    } = useChapterSelection(allChapterIds);

    const {
        importing,
        progress: importProgress,
        importStatus,
        fileInputRef,
        handleFileUpload,
        handleImportJSON
    } = useChapterImport(workspaceId, chapters?.length || 0);

    const dictEntries = useLiveQuery(() => db.dictionary.where("workspaceId").equals(workspaceId).toArray(), [workspaceId]);
    const {
        pendingCharacters,
        pendingTerms,
        isReviewOpen,
        setIsReviewOpen,
        handleAIExtractChapter,
        handleConfirmSaveAI
    } = useAIExtraction(workspaceId, dictEntries || []);

    const queueState = useAiQueueStats();

    // NEW: Dialog states first (needed by other hooks)
    const { translateDialogOpen, setTranslateDialogOpen, historyOpen, setHistoryOpen } = useDialogStates();

    // NEW: Use all extracted hooks
    const {
        handleExport,
        handleInspect,
        handleClearTranslation,
        handleBulkClearTranslation,
        handleBulkDelete,
        handleSanitizeDatabase,
        inspectingChapter,
        isInspectOpen,
        setIsInspectOpen
    } = useChapterActions({ workspaceId, selectedChapters, filtered, setHistoryOpen });

    const { handleApplyCorrections, handleFixTitleCase } = useCorrections({
        workspaceId,
        selectedChapters,
        setHistoryOpen
    });

    const {
        scanConfigOpen,
        setScanConfigOpen,
        handleScan,
        handleStartScan
    } = useScanConfig({ selectedChapters, chapters, handleAIExtractChapter });

    const {
        readingChapterId,
        handleRead,
        handlePrev,
        handleNext,
        handleClose: handleReaderClose,
        hasPrev,
        hasNext
    } = useReaderNavigation({ workspaceId, filtered });

    const totalPages = Math.ceil(filtered.length / itemsPerPage);
    const currentChapters = useMemo(() => {
        const start = (currentPage - 1) * itemsPerPage;
        return filtered.slice(start, start + itemsPerPage);
    }, [filtered, currentPage, itemsPerPage]);

    useEffect(() => { setCurrentPage(1); }, [search, filterStatus]);

    if (!chapters) return <div className="p-10 text-center text-white/50 animate-pulse">Loading workspace...</div>;

    return (
        <div className="space-y-6 animate-in fade-in duration-500 relative pb-10">

            {/* Overlays */}
            <ImportProgressOverlay importing={importing} progress={importProgress} importStatus={importStatus} />

            {/* Header */}
            <ChapterListHeader
                workspaceId={workspaceId}
                totalChapters={chapters.length}
                searchTerm={search}
                setSearchTerm={setSearch}
                filterStatus={filterStatus}
                setFilterStatus={setFilterStatus}
                currentPage={currentPage}
                setCurrentPage={setCurrentPage}
                totalPages={totalPages}
                itemsPerPage={itemsPerPage}
                setItemsPerPage={setItemsPerPage}
                onExport={handleExport}
                fileInputRef={fileInputRef}
                onFileUpload={handleFileUpload}
                onImportJSON={handleImportJSON}
                importing={importing}
                viewMode={viewMode}
                onViewModeChange={setViewMode}
                onScan={handleScan}
                lastReadChapterId={workspace?.lastReadChapterId}
                onReadContinue={handleRead}
                onHistoryOpen={() => setHistoryOpen(true)}
                onApplyCorrections={() => toast.info("Tính năng đang phát triển")}
                onClearCache={handleSanitizeDatabase}
                onFixTitles={() => toast.info("Tính năng đang phát triển")}
                onFixTitleCase={handleFixTitleCase}
            />

            {/* Main Content */}
            <ChapterListContent
                viewMode={viewMode}
                currentChapters={currentChapters}
                selectedChapters={selectedChapters}
                queueState={queueState}
                setSelectedChapters={setSelectedChapters}
                filtered={filtered}
                handleSelect={handleSelect}
                handleRead={handleRead}
                handleInspect={handleInspect}
                handleClearTranslation={handleClearTranslation}
                handleApplyCorrections={handleApplyCorrections}
                fileInputRef={fileInputRef}
            />

            {/* All Dialogs */}
            <ChapterListDialogs
                translateDialogOpen={translateDialogOpen}
                setTranslateDialogOpen={setTranslateDialogOpen}
                selectedChapters={selectedChapters}
                onTranslate={onTranslate}
                workspaceId={workspaceId}
                filtered={filtered}
                onShowScanResults={onShowScanResults}
                isInspectOpen={isInspectOpen}
                setIsInspectOpen={setIsInspectOpen}
                inspectingChapter={inspectingChapter}
                readingChapterId={readingChapterId}
                handleReaderClose={handleReaderClose}
                handlePrev={handlePrev}
                handleNext={handleNext}
                hasPrev={hasPrev}
                hasNext={hasNext}
                historyOpen={historyOpen}
                setHistoryOpen={setHistoryOpen}
                scanConfigOpen={scanConfigOpen}
                setScanConfigOpen={setScanConfigOpen}
                handleStartScan={handleStartScan}
                isReviewOpen={isReviewOpen}
                setIsReviewOpen={setIsReviewOpen}
                pendingCharacters={pendingCharacters}
                pendingTerms={pendingTerms}
                handleConfirmSaveAI={handleConfirmSaveAI}
            />

            {/* Selection Dock */}
            <ChapterSelectionDock
                selectedChapters={selectedChapters}
                isRaidenMode={false}
                setSelectedChapters={setSelectedChapters}
                setTranslateDialogOpen={setTranslateDialogOpen}
                filtered={filtered}
                setTempScanText={() => { }}
                setScanConfigOpen={setScanConfigOpen}
                isAIExtracting={false}
                handleBulkClearTranslation={handleBulkClearTranslation}
                setBulkDeleteConfirmOpen={() => handleBulkDelete()}
            />
        </div>
    );
}

"use client";

import React, { useRef } from "react";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { ChevronDown, Book } from "lucide-react";
import { type Chapter } from "@/lib/db";
import { type AiQueueState } from "@/lib/services/ai-queue";
import { ChapterRow } from "./ChapterRow";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { useVirtualizer } from "@tanstack/react-virtual";
import { useChapterTable } from "../hooks/useChapterTable";
import {
    AlertDialog,
    AlertDialogAction,
    AlertDialogCancel,
    AlertDialogContent,
    AlertDialogDescription,
    AlertDialogFooter,
    AlertDialogHeader,
    AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { AlertTriangle } from "lucide-react";

interface ChapterTableProps {
    chapters: Chapter[];
    selectedChapters: number[];
    queueState: AiQueueState;
    setSelectedChapters: (ids: number[]) => void;
    onSelect: (id: number, shiftKey?: boolean) => void;

    // Selection handlers
    onSelectPage: () => void;
    onSelectGlobal: () => void;
    onDeselectAll: () => void;

    // Actions
    onRead: (id: number) => void;
    onInspect: (id: number) => void;
    onClearTranslation: (id: number) => void;
    onApplyCorrections: () => void;
    lastReadChapterId?: number;
}

export const ChapterTable = React.memo(function ChapterTable(props: ChapterTableProps) {
    const {
        chapters, selectedChapters, queueState, setSelectedChapters, onSelect,
        onSelectPage, onSelectGlobal, onDeselectAll,
        onRead, onInspect, onClearTranslation, onApplyCorrections,
        lastReadChapterId
    } = props;

    const parentRef = useRef<HTMLDivElement>(null);

    const [deleteId, setDeleteId] = React.useState<number | null>(null);

    const { state, actions } = useChapterTable({
        chapters,
        selectedChapters,
        setSelectedChapters
    });

    const { selectedSet, isPageAllSelected, isPageSomeSelected } = state;
    const { handleMouseDown, handleMouseEnter, handleDelete } = actions;

    // Virtualizer for ultra-high performance in large books
    const rowVirtualizer = useVirtualizer({
        count: chapters.length,
        getScrollElement: () => parentRef.current,
        estimateSize: () => 52,
        overscan: 10,
    });

    return (
        <div className="border border-border bg-muted/40 overflow-hidden flex flex-col h-[75vh] shadow-sm rounded-xl transition-all duration-500">
            {/* Virtualized Header - Sticky Grid */}
            <div className="grid grid-cols-[50px_60px_1fr_1fr_140px_100px] bg-muted border-b-2 border-border/80 py-3 px-4 shadow-sm font-semibold text-[10px] uppercase tracking-widest text-muted-foreground z-20 shrink-0 transition-all duration-500">
                <div className="flex items-center gap-1">
                    <Checkbox
                        checked={isPageAllSelected || (isPageSomeSelected && "indeterminate")}
                        onCheckedChange={() => isPageAllSelected ? onDeselectAll() : onSelectPage()}
                    />
                    <Popover>
                        <PopoverTrigger asChild>
                            <Button variant="ghost" size="icon" className="h-4 w-4 p-0 text-muted-foreground hover:text-foreground">
                                <ChevronDown className="h-4 w-4" />
                            </Button>
                        </PopoverTrigger>
                        <PopoverContent className="w-56 p-1" align="start">
                            <div className="grid gap-1">
                                <Button variant="ghost" size="sm" className="justify-start font-normal text-xs" onClick={onSelectPage}>Chọn trang này</Button>
                                <Button variant="ghost" size="sm" className="justify-start font-normal text-xs" onClick={onSelectGlobal}>Chọn TẤT CẢ</Button>
                                <div className="h-px bg-border my-1" />
                                <Button variant="ghost" size="sm" className="justify-start font-normal text-xs text-blue-400" onClick={onApplyCorrections}>
                                    <Book className="mr-2 h-3 w-3" /> Áp dụng Cải chính
                                </Button>
                                <Button variant="ghost" size="sm" className="justify-start font-normal text-xs text-destructive" onClick={onDeselectAll}>Bỏ chọn tất cả</Button>
                            </div>
                        </PopoverContent>
                    </Popover>
                </div>
                <div className="text-center">C.#</div>
                <div>Tiêu đề</div>
                <div>Tiêu đề dịch</div>
                <div className="text-center">Trạng thái</div>
                <div className="text-right pr-4">Hành động</div>
            </div>

            {/* Scrollable Virtual Body */}
            <div
                ref={parentRef}
                className="flex-1 overflow-auto custom-scrollbar relative"
            >
                <div
                    style={{
                        height: `${rowVirtualizer.getTotalSize()}px`,
                        width: '100%',
                        position: 'relative',
                    }}
                >
                    {rowVirtualizer.getVirtualItems().map((virtualRow) => {
                        const chapter = chapters[virtualRow.index];
                        return (
                            <div
                                key={virtualRow.key}
                                style={{
                                    position: 'absolute',
                                    top: 0,
                                    left: 0,
                                    width: '100%',
                                    height: `${virtualRow.size}px`,
                                    transform: `translateY(${virtualRow.start}px)`,
                                }}
                            >
                                <ChapterRow
                                    id={chapter.id!}
                                    order={chapter.order}
                                    index={virtualRow.index}
                                    title={chapter.title}
                                    title_translated={chapter.title_translated}
                                    status={chapter.status || 'draft'}
                                    hasGlossary={!!chapter.glossaryExtractedAt}
                                    issueCount={chapter.inspectionResults?.length || 0}
                                    wordCountOriginal={chapter.wordCountOriginal}
                                    translationModel={chapter.translationModel}
                                    isSelected={selectedSet.has(chapter.id!)}
                                    isInDrag={false}
                                    isLastRead={lastReadChapterId === chapter.id}
                                    hasContent={!!chapter.content_translated && chapter.content_translated.length > 0}
                                    hasTitle={!!chapter.title_translated && chapter.title_translated.length > 0}
                                    queueStatus={
                                        queueState.runningIds.includes(`translate-chap-${chapter.id}`) ? 'running' :
                                            queueState.pendingIds.includes(`translate-chap-${chapter.id}`) ? 'queued' : 'none'
                                    }
                                    onMouseDown={handleMouseDown}
                                    onMouseEnter={handleMouseEnter}
                                    onSelect={onSelect}
                                    onRead={onRead}
                                    onDelete={(id) => setDeleteId(id)}
                                    onInspect={onInspect}
                                    onClearTranslation={onClearTranslation}
                                />
                            </div>
                        );
                    })}
                </div>
            </div>

            <AlertDialog open={!!deleteId} onOpenChange={(open) => !open && setDeleteId(null)}>
                <AlertDialogContent className="max-w-[400px] rounded-3xl border-rose-100 shadow-2xl">
                    <AlertDialogHeader className="items-center text-center">
                        <div className="h-16 w-16 rounded-full bg-rose-50 flex items-center justify-center mb-2">
                            <AlertTriangle className="h-8 w-8 text-rose-500 animate-bounce" />
                        </div>
                        <AlertDialogTitle className="text-xl font-bold text-slate-900">Xác nhận xóa chương?</AlertDialogTitle>
                        <AlertDialogDescription className="text-slate-500">
                            Bạn sắp xóa vĩnh viễn chương truyện này khỏi thư viện. Hành động này không thể hoàn tác.
                        </AlertDialogDescription>
                    </AlertDialogHeader>
                    <AlertDialogFooter className="sm:justify-center gap-2 pt-4">
                        <AlertDialogCancel className="rounded-2xl border-slate-200 text-slate-600 hover:bg-slate-50 px-8">Hủy</AlertDialogCancel>
                        <AlertDialogAction
                            onClick={async () => {
                                if (deleteId) {
                                    await handleDelete(deleteId);
                                    setDeleteId(null);
                                }
                            }}
                            className="rounded-2xl bg-rose-500 hover:bg-rose-600 text-white border-0 px-8 shadow-lg shadow-rose-200"
                        >
                            Xác nhận Xóa
                        </AlertDialogAction>
                    </AlertDialogFooter>
                </AlertDialogContent>
            </AlertDialog>
        </div>
    );
});

