"use client";

import React, { createContext, useContext, ReactNode } from "react";
import { useReaderConfig } from "../hooks/useReaderConfig";
import { InspectionIssue } from "@/lib/types";
import { useReaderTTS } from "../hooks/useReaderTTS";
import { useReaderInspection } from "../hooks/useReaderInspection";
import { useReaderSelection } from "../hooks/useReaderSelection";

interface ReaderContextValue {
    // Config
    readerConfig: ReturnType<typeof useReaderConfig>["readerConfig"];
    setReaderConfig: ReturnType<typeof useReaderConfig>["setReaderConfig"];
    updateConfig: ReturnType<typeof useReaderConfig>["updateConfig"];
    showSettings: boolean;
    setShowSettings: (show: boolean) => void;

    // TTS
    isTTSPlaying: boolean;
    isTTSLoading: boolean;
    activeTTSIndex: number | null;
    ttsSegments: string[];
    handleTTSPlay: (index: number) => Promise<void>;
    handleTTSStop: () => void;
    handleTTSToggle: () => void;

    // Inspection
    isInspecting: boolean;
    inspectionIssues: InspectionIssue[];
    setInspectionIssues: (issues: InspectionIssue[]) => void;
    activeIssue: InspectionIssue | null;
    setActiveIssue: (issue: InspectionIssue | null) => void;
    handleInspect: (content: string) => Promise<InspectionIssue[] | null | undefined>;
    handleApplyFix: (issue: InspectionIssue, content: string, save: boolean, update: (c: string) => void) => Promise<void>;

    // Selection
    menuPosition: { x: number, y: number } | null;
    setMenuPosition: (pos: { x: number, y: number } | null) => void;
    contextMenuPosition: { x: number, y: number } | null;
    setContextMenuPosition: (pos: { x: number, y: number } | null) => void;
    selectedText: string;
    setSelectedText: (text: string) => void;
    editorRef: React.RefObject<HTMLDivElement | null>;
    handleTextSelection: () => void;
    handleContextMenu: (e: React.MouseEvent) => void;
    clearSelection: () => void;

    // Chapter data
    chapter: any;
    chapterId: number;
}

const ReaderContext = createContext<ReaderContextValue | null>(null);

export function useReaderContext() {
    const context = useContext(ReaderContext);
    if (!context) {
        throw new Error("useReaderContext must be used within ReaderProvider");
    }
    return context;
}

interface ReaderProviderProps {
    children: ReactNode;
    chapterId: number;
    chapter: any;
}

export function ReaderProvider({ children, chapterId, chapter }: ReaderProviderProps) {
    const config = useReaderConfig();
    const selection = useReaderSelection();
    const inspection = useReaderInspection(chapterId, chapter);
    const tts = useReaderTTS(
        chapterId,
        chapter?.content_translated,
        config.readerConfig
    );

    const value: ReaderContextValue = {
        // Config
        readerConfig: config.readerConfig,
        setReaderConfig: config.setReaderConfig,
        updateConfig: config.updateConfig,
        showSettings: config.showSettings,
        setShowSettings: config.setShowSettings,

        // TTS
        isTTSPlaying: tts.isTTSPlaying,
        isTTSLoading: tts.isTTSLoading,
        activeTTSIndex: tts.activeTTSIndex,
        ttsSegments: [],
        handleTTSPlay: async () => { },
        handleTTSStop: tts.stopTTS,
        handleTTSToggle: tts.toggleTTS,

        // Inspection
        isInspecting: inspection.isInspecting,
        inspectionIssues: inspection.inspectionIssues,
        setInspectionIssues: inspection.setInspectionIssues,
        activeIssue: inspection.activeIssue,
        setActiveIssue: inspection.setActiveIssue,
        handleInspect: inspection.handleInspect,
        handleApplyFix: inspection.handleApplyFix,

        // Selection
        menuPosition: selection.menuPosition,
        setMenuPosition: selection.setMenuPosition,
        contextMenuPosition: selection.contextMenuPosition,
        setContextMenuPosition: selection.setContextMenuPosition,
        selectedText: selection.selectedText,
        setSelectedText: selection.setSelectedText,
        editorRef: selection.editorRef,
        handleTextSelection: selection.handleTextSelection,
        handleContextMenu: selection.handleContextMenu,
        clearSelection: selection.clearSelection,

        // Chapter data
        chapter,
        chapterId,
    };

    return (
        <ReaderContext.Provider value={value}>
            {children}
        </ReaderContext.Provider>
    );
}

"use client";

import { useState, useMemo, useCallback } from "react";
import { useLiveQuery } from "dexie-react-hooks";
import { db } from "@/lib/db";
import { translateTerms } from "@/lib/gemini";
import { toast } from "sonner";

export function useBlacklist(workspaceId: string) {
    const blacklist = useLiveQuery(
        () => db.blacklist.where('workspaceId').equals(workspaceId).toArray(),
        [workspaceId]
    ) || [];
    const [sourceFilter, setSourceFilter] = useState<'all' | 'content' | 'engine'>('all');

    const [blacklistSearch, setBlacklistSearch] = useState("");
    const [selectedBlacklist, setSelectedBlacklist] = useState<number[]>([]);
    const [isTranslating, setIsTranslating] = useState(false);

    const filteredBlacklist = useMemo(() => {
        return blacklist
            .filter(b => {
                // Search
                const matchesSearch = b.word.toLowerCase().includes(blacklistSearch.toLowerCase()) ||
                    (b.translated && b.translated.toLowerCase().includes(blacklistSearch.toLowerCase()));

                if (!matchesSearch) return false;

                // Source Filter
                if (sourceFilter === 'content') return b.source === 'ai' || b.source === 'manual';
                if (sourceFilter === 'engine') return b.source === 'heuristic';

                return true;
            })
            .sort((a, b) => (b.id || 0) - (a.id || 0));
    }, [blacklist, blacklistSearch, sourceFilter]);

    const handleRestoreBlacklist = useCallback(async (id: number) => {
        const item = blacklist.find(b => b.id === id);
        if (!item) return;

        await db.blacklist.delete(id);

        const existing = await db.dictionary.where({ original: item.word, workspaceId }).first();
        if (!existing) {
            await db.dictionary.add({
                workspaceId,
                original: item.word,
                translated: item.translated || item.word,
                type: 'general',
                createdAt: new Date()
            });
        }
        toast.success("Đã khôi phục từ Blacklist.");
    }, [blacklist, workspaceId]);

    const handleBulkRestoreBlacklist = useCallback(async () => {
        if (!selectedBlacklist.length) return;
        if (confirm(`Khôi phục (Bỏ chặn) ${selectedBlacklist.length} từ?`)) {
            const itemsToRestore = blacklist.filter(b => selectedBlacklist.includes(b.id!));
            await db.blacklist.bulkDelete(selectedBlacklist);

            const now = new Date();
            for (const item of itemsToRestore) {
                const existing = await db.dictionary.where({ original: item.word, workspaceId }).first();
                if (!existing) {
                    await db.dictionary.add({
                        workspaceId,
                        original: item.word,
                        translated: item.translated || item.word,
                        type: 'general',
                        createdAt: now
                    });
                }
            }
            setSelectedBlacklist([]);
            toast.success(`Đã khôi phục ${itemsToRestore.length} từ.`);
        }
    }, [selectedBlacklist, blacklist, workspaceId]);

    const handleTranslateBlacklist = useCallback(async () => {
        const missingMeanings = blacklist.filter(b => !b.translated || b.translated === b.word);
        if (missingMeanings.length === 0) {
            toast.info("Tất cả các mục đều đã có nghĩa dịch.");
            return;
        }

        setIsTranslating(true);
        try {
            const termsToTranslate = missingMeanings.map(b => b.word);
            const chunkSize = 50;
            for (let i = 0; i < termsToTranslate.length; i += chunkSize) {
                const chunk = termsToTranslate.slice(i, i + chunkSize);
                const results = await translateTerms(chunk);

                for (const res of results) {
                    const item = missingMeanings.find(b => b.word === res.original);
                    if (item) {
                        await db.blacklist.update(item.id!, { translated: res.translated });
                    }
                }
            }
            toast.success(`Đã cập nhật nghĩa cho ${missingMeanings.length} mục trong Blacklist.`);
        } catch (error: any) {
            console.error(error);
            if (error.message?.includes('network')) {
                toast.error("Lỗi mạng. Kiểm tra kết nối.");
            } else {
                toast.error("Lỗi khi dịch Blacklist");
            }
        } finally {
            setIsTranslating(false);
        }
    }, [blacklist]);

    const handleBlacklistExport = useCallback(() => {
        const data = blacklist.map(e => ({
            word: e.word,
            translated: e.translated,
            source: e.source,
            createdAt: e.createdAt
        }));
        const jsonString = JSON.stringify(data, null, 2);
        const blob = new Blob([jsonString], { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'blacklist.json';
        a.click();
        URL.revokeObjectURL(url); // Cleanup
        toast.success("Đã export Blacklist.");
    }, [blacklist]);

    const handleBlacklistImport = useCallback(async (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        const reader = new FileReader();
        reader.onload = async (event) => {
            try {
                const text = event.target?.result as string;
                const data = JSON.parse(text);
                let imported = 0;

                for (const item of data) {
                    const existing = await db.blacklist.where({ word: item.word, workspaceId }).first();
                    if (!existing) {
                        await db.blacklist.add({
                            workspaceId,
                            word: item.word,
                            translated: item.translated || item.word,
                            source: item.source || 'manual',
                            createdAt: new Date(item.createdAt || Date.now())
                        });
                        imported++;
                    }
                }
                toast.success(`Import thành công: ${imported} mục mới.`);
            } catch (err) {
                console.error(err);
                toast.error("Lỗi import file.");
            }
        };
        reader.readAsText(file);
        e.target.value = '';
    }, [workspaceId]);

    const handleHeuristicExport = useCallback(async () => {
        const engineTerms = blacklist.filter(b => b.source === 'heuristic');
        if (engineTerms.length === 0) {
            toast.error("Không có mẫu vật (Heuristic) để xuất!");
            return;
        }

        try {
            const { writeTextFile, BaseDirectory } = await import('@tauri-apps/plugin-fs');
            const content = engineTerms.map(b => b.word).join('\n');
            const filename = `heuristic_engine_samples_${new Date().getTime()}.txt`;
            await writeTextFile(filename, content, { baseDir: BaseDirectory.Desktop });
            toast.success(`✅ Đã xuất ${engineTerms.length} mẫu vật ra Desktop/`, {
                description: filename
            });
        } catch (err) {
            toast.error("Lỗi xuất file: " + String(err));
        }
    }, [blacklist]);

    const handleClearHeuristic = useCallback(async () => {
        const engineTerms = blacklist.filter(b => b.source === 'heuristic');
        if (engineTerms.length === 0) return;

        if (confirm(`⚠️ Xóa toàn bộ ${engineTerms.length} mẫu vật Heuristic để chuẩn bị vòng lặp mới?`)) {
            await db.blacklist
                .where('[workspaceId+source]')
                .equals([workspaceId, 'heuristic'])
                .delete();
            toast.success("Đã dọn sạch bộ nhớ Engine. Sẵn sàng quét lại!");
        }
    }, [blacklist, workspaceId]);

    return {
        blacklist,
        filteredBlacklist,
        blacklistSearch,
        setBlacklistSearch,
        selectedBlacklist,
        setSelectedBlacklist,
        sourceFilter,
        setSourceFilter,
        isTranslating,
        handleRestoreBlacklist,
        handleBulkRestoreBlacklist,
        handleTranslateBlacklist,
        handleBlacklistExport,
        handleBlacklistImport,
        handleHeuristicExport,
        handleClearHeuristic,
        workspaceId
    };
}

"use client";

import { useState, useMemo, useCallback } from "react";
import { useLiveQuery } from "dexie-react-hooks";
import { db } from "@/lib/db";
import { toast } from "sonner";
import { useDictionaryAI } from "./useDictionaryAI";

export function useDictionary(workspaceId: string) {
    // Data
    const dictionary = useLiveQuery(
        () => db.dictionary.where('workspaceId').equals(workspaceId).toArray(),
        [workspaceId]
    ) || [];

    // State
    const [search, setSearch] = useState("");
    const [filterType, setFilterType] = useState<string>("all");
    const [isAdding, setIsAdding] = useState(false);
    const [newOriginal, setNewOriginal] = useState("");
    const [newTranslated, setNewTranslated] = useState("");
    const [newType, setNewType] = useState("general");
    const [selectedEntries, setSelectedEntries] = useState<number[]>([]);

    // AI Hook
    const aiHook = useDictionaryAI(workspaceId);

    // Filtered data with useMemo for performance
    const filteredDic = useMemo(() => {
        return dictionary
            .filter(d => d.type !== 'name')
            .filter(d => filterType === "all" || d.type === filterType)
            .filter(d =>
                d.original.toLowerCase().includes(search.toLowerCase()) ||
                d.translated.toLowerCase().includes(search.toLowerCase())
            )
            .sort((a, b) => (a.id || 0) - (b.id || 0));
    }, [dictionary, filterType, search]);

    // Handlers with useCallback
    const handleAdd = useCallback(async () => {
        if (!newOriginal || !newTranslated || !workspaceId) return;
        try {
            const existing = await db.dictionary
                .where('[workspaceId+original]')
                .equals([workspaceId, newOriginal])
                .first();

            if (existing) {
                await db.dictionary.update(existing.id!, {
                    translated: newTranslated,
                    type: newType as any,
                    createdAt: new Date()
                });
            } else {
                await db.dictionary.add({
                    workspaceId,
                    original: newOriginal,
                    translated: newTranslated,
                    type: newType as any,
                    createdAt: new Date()
                });
            }
            setNewOriginal("");
            setNewTranslated("");
            setNewType("general");
            setIsAdding(false);
        } catch (e) {
            console.error(e);
        }
    }, [newOriginal, newTranslated, newType, workspaceId]);

    const handleDelete = useCallback(async (id: number) => {
        try {
            await db.dictionary.delete(id);
            toast.success("Đã xóa thuật ngữ.");
        } catch (e) {
            console.error("Delete failed:", e);
            toast.error("Lỗi khi xóa.");
        }
    }, []);

    const handleUpdateType = useCallback(async (id: number, type: string) => {
        await db.dictionary.update(id, { type: type as any });
    }, []);

    const handleBulkDelete = useCallback(async () => {
        if (!selectedEntries.length) return;
        if (confirm(`Xóa ${selectedEntries.length} mục đã chọn?`)) {
            await db.dictionary.bulkDelete(selectedEntries);
            setSelectedEntries([]);
        }
    }, [selectedEntries]);

    const handleBulkUpdateType = useCallback(async (type: string) => {
        if (!selectedEntries.length) return;
        await db.dictionary.where('id').anyOf(selectedEntries).modify({ type: type as any });
    }, [selectedEntries]);

    const toggleSelectAll = useCallback(() => {
        if (selectedEntries.length === filteredDic.length) {
            setSelectedEntries([]);
        } else {
            setSelectedEntries(filteredDic.map(d => d.id!));
        }
    }, [selectedEntries.length, filteredDic]);

    const handleBlacklist = useCallback(async (id: number) => {
        try {
            const item = await db.dictionary.get(id);
            if (item) {
                await db.blacklist.add({
                    workspaceId,
                    word: item.original,
                    translated: item.translated,
                    source: 'manual',
                    createdAt: new Date()
                });
                await db.dictionary.delete(id);
                toast.success("Đã chuyển vào Blacklist.");
            }
        } catch (e) {
            console.error(e);
            toast.error("Lỗi khi chuyển vào Blacklist.");
        }
    }, [workspaceId]);

    const handleImport = useCallback(async (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        const reader = new FileReader();
        reader.onload = async (event) => {
            try {
                const text = event.target?.result as string;
                const lines = text.split('\n').filter(l => l.trim());
                let imported = 0;
                let updated = 0;

                for (const line of lines) {
                    const [original, translated, type] = line.split('\t');
                    if (!original || !translated) continue;

                    const existing = await db.dictionary.where('[workspaceId+original]').equals([workspaceId, original]).first();
                    if (existing) {
                        await db.dictionary.update(existing.id!, {
                            translated,
                            type: (type || 'general') as any,
                            createdAt: new Date()
                        });
                        updated++;
                    } else {
                        await db.dictionary.add({
                            workspaceId,
                            original,
                            translated,
                            type: (type || 'general') as any,
                            createdAt: new Date()
                        });
                        imported++;
                    }
                }
                toast.success(`Import thành công: ${imported} mới, ${updated} cập nhật.`);
            } catch (err) {
                console.error(err);
                toast.error("Lỗi import file.");
            }
        };
        reader.readAsText(file);
        e.target.value = '';
    }, [workspaceId]);

    const handleExport = useCallback(async () => {
        const data = dictionary.map(d => `${d.original}\t${d.translated}\t${d.type}`).join('\n');
        const blob = new Blob([data], { type: 'text/plain' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'dictionary.txt';
        a.click();
        URL.revokeObjectURL(url); // Cleanup
    }, [dictionary]);

    const handleExportJSON = useCallback(async () => {
        const fileName = `dictionary-export-${new Date().getTime()}.json`;
        const content = JSON.stringify(dictionary, null, 2);

        // 1. Try Tauri Native Save Dialog if available
        if (typeof window !== 'undefined' && (window as unknown as { __TAURI_INTERNALS__?: unknown }).__TAURI_INTERNALS__) {
            try {
                const { save } = await import("@tauri-apps/plugin-dialog");
                const { writeTextFile } = await import("@tauri-apps/plugin-fs");

                const path = await save({
                    defaultPath: fileName,
                    filters: [{ name: 'JSON', extensions: ['json'] }]
                });

                if (path) {
                    await writeTextFile(path, content);
                    toast.success("Đã xuất từ điển thành công!");
                    return;
                }
                return; // Canceled
            } catch (err) {
                console.error("Tauri Export Error:", err);
            }
        }

        // 2. Fallback to standard Browser download
        const blob = new Blob([content], { type: "application/json" });
        const url = URL.createObjectURL(blob);
        const a = document.createElement("a");
        a.href = url;
        a.download = fileName;
        a.click();
        URL.revokeObjectURL(url);
        toast.success("Đã xuất từ điển thành công!");
    }, [dictionary]);

    const handleImportJSON = useCallback(async () => {
        let text = "";

        // 1. Try Tauri Native Dialog if available
        if (typeof window !== 'undefined' && (window as unknown as { __TAURI_INTERNALS__?: unknown }).__TAURI_INTERNALS__) {
            try {
                const { open } = await import("@tauri-apps/plugin-dialog");
                const { readTextFile } = await import("@tauri-apps/plugin-fs");

                const selected = await open({
                    filters: [{ name: 'JSON', extensions: ['json'] }],
                    multiple: false
                });

                if (selected && typeof selected === 'string') {
                    text = await readTextFile(selected);
                } else if (selected && typeof selected === 'object' && 'path' in selected) {
                    text = await readTextFile((selected as { path: string }).path);
                } else {
                    return; // Canceled
                }
            } catch (err) {
                console.error("Tauri Import Error:", err);
                toast.error("Lỗi khi mở file JSON.");
                return;
            }
        } else {
            // 2. Fallback to standard file input for web
            const input = document.createElement('input');
            input.type = 'file';
            input.accept = '.json';
            input.onchange = async (e) => {
                const file = (e.target as HTMLInputElement).files?.[0];
                if (file) {
                    text = await file.text();
                    await processJSONImport(text);
                }
            };
            input.click();
            return;
        }

        await processJSONImport(text);

        async function processJSONImport(jsonText: string) {
            try {
                const data = JSON.parse(jsonText);
                if (!Array.isArray(data)) {
                    toast.error("Định dạng JSON không hợp lệ.");
                    return;
                }

                let imported = 0;
                let updated = 0;

                for (const item of data) {
                    if (!item.original || !item.translated) continue;

                    const existing = await db.dictionary
                        .where('[workspaceId+original]')
                        .equals([workspaceId, item.original])
                        .first();

                    if (existing) {
                        await db.dictionary.update(existing.id!, {
                            translated: item.translated,
                            type: (item.type || 'general') as any,
                            description: item.description,
                            createdAt: new Date()
                        });
                        updated++;
                    } else {
                        await db.dictionary.add({
                            workspaceId,
                            original: item.original,
                            translated: item.translated,
                            type: (item.type || 'general') as any,
                            description: item.description,
                            createdAt: new Date()
                        });
                        imported++;
                    }
                }

                toast.success(`Nhập thành công: ${imported} mới, ${updated} cập nhật.`);
            } catch (err) {
                console.error(err);
                toast.error("Lỗi khi nhập file JSON.");
            }
        }
    }, [workspaceId]);

    return {
        dictionary,
        filteredDic,
        search,
        setSearch,
        filterType,
        setFilterType,
        selectedEntries,
        setSelectedEntries,
        isAdding,
        setIsAdding,
        newOriginal,
        setNewOriginal,
        newTranslated,
        setNewTranslated,
        newType,
        setNewType,
        ...aiHook,
        handleAdd,
        handleDelete,
        handleUpdateType,
        handleBulkDelete,
        handleBulkUpdateType,
        toggleSelectAll,
        handleBlacklist,
        handleImport,
        handleExport,
    };
}

import { useState, useCallback } from "react";
import { extractGlossary, categorizeTerms } from "@/lib/gemini";
import { db } from "@/lib/db";
import { toast } from "sonner";
import { GlossaryCharacter, GlossaryTerm, GlossaryResult } from "@/lib/types";

export function useDictionaryAI(workspaceId: string) {
    const [isExtracting, setIsExtracting] = useState(false);
    const [extractDialogOpen, setExtractDialogOpen] = useState(false);
    const [pendingCharacters, setPendingCharacters] = useState<GlossaryCharacter[]>([]);
    const [pendingTerms, setPendingTerms] = useState<GlossaryTerm[]>([]);
    const [isReviewOpen, setIsReviewOpen] = useState(false);

    const handleAIExtract = useCallback(async (source: "latest" | "current" | "select", dictionary: any[]) => {
        if (!workspaceId) return;
        setIsExtracting(true);
        try {
            const chapters = await db.chapters.where("workspaceId").equals(workspaceId).toArray();
            if (chapters.length === 0) {
                toast.warning("Chưa có chương nào để phân tích!");
                setIsExtracting(false);
                return;
            }

            let targetChapter: any;
            if (source === "latest") {
                chapters.sort((a, b) => b.order - a.order);
                targetChapter = chapters[0];
            } else if (source === "current") {
                chapters.sort((a, b) => b.id! - a.id!);
                targetChapter = chapters[0];
            }

            if (!targetChapter) {
                toast.error("Không tìm thấy chương để quét.");
                setIsExtracting(false);
                return;
            }

            toast.info(`Đang quét: ${targetChapter.title}...`);
            const result: GlossaryResult | null = await extractGlossary(targetChapter.content_original);

            if (result) {
                const existingOriginals = new Set(dictionary.map(d => d.original));

                const newChars: GlossaryCharacter[] = result.characters.map((c) => ({
                    ...c,
                    isExisting: existingOriginals.has(c.original)
                }));

                const newTerms: GlossaryTerm[] = result.terms.map((t) => ({
                    ...t,
                    isExisting: existingOriginals.has(t.original)
                }));

                setPendingCharacters(newChars);
                setPendingTerms(newTerms);
                setIsReviewOpen(true);

                if (targetChapter?.id) {
                    await db.chapters.update(targetChapter.id, {
                        glossaryExtractedAt: new Date()
                    });
                    toast.success(`Đã đánh dấu chương "${targetChapter.title}" là đã quét thuật ngữ.`);
                }
            } else {
                toast.info("AI không trả về kết quả nào.");
            }
        } catch (e: any) {
            console.error("Extraction error", e);
            // Better error handling
            if (e.message?.includes('network')) {
                toast.error("Lỗi mạng. Kiểm tra kết nối internet.");
            } else if (e.message?.includes('quota')) {
                toast.error("Hết quota API. Đợi hoặc đổi API key.");
            } else {
                toast.error(`Lỗi: ${e.message || 'Unknown error'}`);
            }
        } finally {
            setIsExtracting(false);
            setExtractDialogOpen(false);
        }
    }, [workspaceId]);

    const handleBulkAICategorize = useCallback(async (selectedEntries: number[]) => {
        if (!selectedEntries.length) return;
        setIsExtracting(true);
        try {
            const entries = await db.dictionary.where('id').anyOf(selectedEntries).toArray();
            const terms = entries.map(e => e.original);

            const chunkSize = 50;
            for (let i = 0; i < terms.length; i += chunkSize) {
                const chunk = terms.slice(i, i + chunkSize);
                const results = await categorizeTerms(chunk);

                for (const res of results) {
                    if (res.category === 'trash') {
                        const entry = await db.dictionary.where({ original: res.original, workspaceId }).first();
                        await db.blacklist.add({
                            workspaceId,
                            word: res.original,
                            translated: entry?.translated || res.original,
                            source: 'ai',
                            createdAt: new Date()
                        });
                        await db.dictionary.where({ original: res.original, workspaceId }).delete();
                    } else {
                        await db.dictionary.where({ original: res.original, workspaceId }).modify({ type: res.category as any });
                    }
                }
            }
        } catch (error: any) {
            console.error(error);
            if (error.message?.includes('network')) {
                toast.error("Lỗi mạng. Kiểm tra kết nối.");
            } else {
                toast.error("Lỗi AI phân loại");
            }
        } finally {
            setIsExtracting(false);
        }
    }, [workspaceId]);

    const handleConfirmSave = useCallback(async (
        saveChars: GlossaryCharacter[],
        saveTerms: GlossaryTerm[],
        blacklistChars: GlossaryCharacter[],
        blacklistTerms: GlossaryTerm[]
    ) => {
        let addedCount = 0;
        let updatedCount = 0;
        let blacklistCount = 0;

        try {
            for (const char of saveChars) {
                const existing = await db.dictionary.where({ original: char.original, workspaceId }).first();
                if (existing) {
                    await db.dictionary.update(existing.id!, {
                        translated: char.translated,
                        type: char.type || 'name',
                        description: char.description,
                        createdAt: new Date()
                    });
                    updatedCount++;
                } else {
                    await db.dictionary.add({
                        workspaceId,
                        original: char.original,
                        translated: char.translated,
                        type: char.type || 'name',
                        description: char.description,
                        createdAt: new Date()
                    });
                    addedCount++;
                }
            }

            for (const term of saveTerms) {
                const existing = await db.dictionary.where({ original: term.original, workspaceId }).first();
                if (existing) {
                    await db.dictionary.update(existing.id!, {
                        translated: term.translated,
                        type: term.type || 'general',
                        description: term.description,
                        createdAt: new Date()
                    });
                    updatedCount++;
                } else {
                    await db.dictionary.add({
                        workspaceId,
                        original: term.original,
                        translated: term.translated,
                        type: term.type || 'general',
                        description: term.description,
                        createdAt: new Date()
                    });
                    addedCount++;
                }
            }

            for (const char of blacklistChars) {
                await db.blacklist.add({
                    workspaceId,
                    word: char.original,
                    translated: char.translated || char.original,
                    source: 'ai',
                    createdAt: new Date()
                });
                blacklistCount++;
            }

            for (const term of blacklistTerms) {
                await db.blacklist.add({
                    workspaceId,
                    word: term.original,
                    translated: term.translated || term.original,
                    source: 'ai',
                    createdAt: new Date()
                });
                blacklistCount++;
            }

            toast.success(`Đã lưu: ${addedCount} mới, ${updatedCount} cập nhật, ${blacklistCount} blacklist.`);
            setIsReviewOpen(false);
            setPendingCharacters([]);
            setPendingTerms([]);
        } catch (e) {
            console.error(e);
            toast.error("Lỗi khi lưu dữ liệu.");
        }
    }, [workspaceId]);

    return {
        isExtracting,
        extractDialogOpen,
        setExtractDialogOpen,
        pendingCharacters,
        pendingTerms,
        isReviewOpen,
        setIsReviewOpen,
        handleAIExtract,
        handleBulkAICategorize,
        handleConfirmSave,
    };
}

"use client";

import React, { useRef } from "react";
import { useVirtualizer } from "@tanstack/react-virtual";
import { DictionaryToolbar } from "../DictionaryToolbar";
import { DictionaryAddForm } from "../DictionaryAddForm";
import { DictionaryBulkActions } from "../DictionaryBulkActions";
import { useDictionary } from "../hooks/useDictionary";
import { Checkbox } from "@/components/ui/checkbox";
import { toast } from "sonner";
import { DictionaryRow } from "../DictionaryRow";
import { useRaiden } from "@/components/theme/RaidenProvider";
import { cn } from "@/lib/utils";

interface DictionaryViewProps {
    workspaceId: string;
    onChangeTab: (tab: string) => void;
}

export function DictionaryView({ workspaceId, onChangeTab }: DictionaryViewProps) {
    const {
        dictionary,
        filteredDic,
        search,
        setSearch,
        filterType,
        setFilterType,
        selectedEntries,
        setSelectedEntries,
        isAdding,
        setIsAdding,
        newOriginal,
        setNewOriginal,
        newTranslated,
        setNewTranslated,
        newType,
        setNewType,
        isExtracting,
        extractDialogOpen,
        setExtractDialogOpen,
        handleAdd,
        handleDelete,
        handleUpdateType,
        handleBulkDelete,
        handleBulkUpdateType,
        toggleSelectAll,
        handleBlacklist,
        handleImport,
        handleExport,
        handleAIExtract,
        handleBulkAICategorize,
    } = useDictionary(workspaceId);
    const { isRaidenMode } = useRaiden();

    // Virtual scrolling setup
    const parentRef = useRef<HTMLDivElement>(null);

    const virtualizer = useVirtualizer({
        count: filteredDic.length,
        getScrollElement: () => parentRef.current,
        estimateSize: () => 70, // Estimated row height
        overscan: 5, // Render 5 extra items above/below viewport
    });

    const handleSelectChange = React.useCallback((id: number, checked: boolean) => {
        if (checked) setSelectedEntries((prev: number[]) => [...prev, id]);
        else setSelectedEntries((prev: number[]) => prev.filter((eId: number) => eId !== id));
    }, [setSelectedEntries]);

    return (
        <div className="space-y-6">
            <DictionaryToolbar
                search={search}
                onSearchChange={setSearch}
                filterType={filterType}
                onFilterTypeChange={setFilterType}
                onImport={handleImport}
                onExport={handleExport}
                onAIExtract={(source: string) => handleAIExtract(source as 'latest' | 'current' | 'select', dictionary)}
                isExtracting={isExtracting}
                extractDialogOpen={extractDialogOpen}
                onExtractDialogChange={setExtractDialogOpen}
                onAddClick={() => setIsAdding(!isAdding)}
                onSelectFromList={() => {
                    setExtractDialogOpen(false);
                    onChangeTab("chapters");
                    toast.info("Mày hãy chọn các chương muốn quét ở danh sách rồi bấm Quét nhé!");
                }}
                workspaceId={workspaceId}
                totalCount={dictionary.length}
            />

            {isAdding && (
                <DictionaryAddForm
                    newOriginal={newOriginal}
                    newTranslated={newTranslated}
                    newType={newType}
                    onOriginalChange={setNewOriginal}
                    onTranslatedChange={setNewTranslated}
                    onTypeChange={setNewType}
                    onAdd={handleAdd}
                />
            )}

            <DictionaryBulkActions
                selectedCount={selectedEntries.length}
                onBulkDelete={handleBulkDelete}
                onBulkAICategorize={() => handleBulkAICategorize(selectedEntries)}
                onBulkUpdateType={handleBulkUpdateType}
                isExtracting={isExtracting}
            />

            {/* Virtual Scrolling Table */}
            <div className={cn(
                "rounded-xl overflow-hidden shadow-sm border transition-all duration-500",
                isRaidenMode ? "bg-card border-border shadow-2xl" : "bg-muted/30 border-border shadow-sm"
            )}>
                {/* Header */}
                <div className={cn(
                    "grid grid-cols-[40px_1fr_1fr_120px_110px] gap-4 px-4 py-3 border-b-2 text-[11px] font-semibold uppercase tracking-wider sticky top-0 z-20 shadow-sm transition-all duration-500",
                    isRaidenMode ? "bg-card border-border text-muted-foreground" : "bg-muted/50 border-border-strong text-foreground/80"
                )}>
                    <div className="flex justify-center items-center">
                        <Checkbox
                            checked={filteredDic.length > 0 && selectedEntries.length === filteredDic.length}
                            onCheckedChange={toggleSelectAll}
                            className={cn(
                                isRaidenMode
                                    ? "border-slate-600 data-[state=checked]:bg-primary data-[state=checked]:border-primary"
                                    : "border-slate-300 data-[state=checked]:bg-primary data-[state=checked]:border-primary"
                            )}
                        />
                    </div>
                    <div className="px-2 flex items-center">Thuật ngữ gốc</div>
                    <div className="px-2 flex items-center">Bản dịch</div>
                    <div className="px-2 flex items-center">Phân loại</div>
                    <div className="text-right pr-4 flex items-center justify-end">Actions</div>
                </div>

                {/* Virtual Rows */}
                <div
                    ref={parentRef}
                    className="h-[calc(100vh-300px)] overflow-y-auto scrollbar-hide"
                >
                    {filteredDic.length === 0 ? (
                        <div className="p-8 text-center text-muted-foreground italic">
                            Chưa có dữ liệu từ điển
                        </div>
                    ) : (
                        <div
                            style={{
                                height: `${virtualizer.getTotalSize()}px`,
                                width: '100%',
                                position: 'relative',
                            }}
                        >
                            {virtualizer.getVirtualItems().map((virtualRow) => (
                                <DictionaryRow
                                    key={virtualRow.key}
                                    index={virtualRow.index}
                                    entry={filteredDic[virtualRow.index]}
                                    isSelected={selectedEntries.includes(filteredDic[virtualRow.index].id!)}
                                    virtualRow={virtualRow}
                                    onSelectChange={handleSelectChange}
                                    onUpdateType={handleUpdateType}
                                    onBlacklist={handleBlacklist}
                                    onDelete={handleDelete}
                                />
                            ))}
                        </div>
                    )}
                </div>
            </div>
            <div className="text-center text-xs text-muted-foreground mt-4">
                Hiển thị {filteredDic.length} kết quả
            </div>
        </div>
    );
}

