                <Button
                    size="sm"
                    variant="ghost"
                    className={cn("h-7 px-2 text-xs hover:bg-white/10", isReaderMode && "bg-emerald-500/20 text-emerald-400")}
                    onClick={() => {
                        const nextState = !isReaderMode;
