// Copy of the fixed normalizer from gemini.ts
function normalizeVietnameseContent(text: string): string {
    if (!text) return "";

    // ULTRA AGGRESSIVE: First, handle the specific case of ".\n\n]" (period, double newline, orphaned bracket)
    // This is the pattern we see in the user's text
    text = text
        // 1. Normalize Brackets: 【 】 -> [ ]
        .replace(/【/g, "[")
        .replace(/】/g, "]")
        // 2. Normalize Parentheses: （ ） -> ( )
        .replace(/（/g, "(")
        .replace(/）/g, ")")

        // 3. MOST CRITICAL: Remove ANY amount of whitespace/newlines before ]
        // This catches patterns like "text.\n]", "text.\n\n]", "text. \n \n ]", etc.
        .replace(/[\s\n]+\]/g, "]")

        // 4. CRITICAL: Handle orphaned ] at start of line (most aggressive fix first)
        // Pattern: "text.\n\n] [next" -> "text.] [next"
        .replace(/\.[\s\n]+\][\s\n]+\[/g, ".] [")

        // 5. Remove ALL whitespace/newlines INSIDE brackets
        .replace(/\[([\s\S]*?)\]/g, (match) => {
            const inner = match.slice(1, -1);
            const cleaned = inner.replace(/\s+/g, " ").trim();
            return `[${cleaned}]`;
        })
        .replace(/\(([^\)]*?)\)/g, (match) => {
            const inner = match.slice(1, -1);
            const cleaned = inner.replace(/\s+/g, " ").trim();
            return `(${cleaned})`;
        })

        // 6. Remove newlines/spaces *after* opening brackets
        .replace(/\[[\s\n]+/g, "[")

        // 7. Squash newline between brackets
        .replace(/\][\s\n]+\[/g, "] [")

        // 8. Remove single newline after ] (keep double for paragraph breaks)
        .replace(/\]\n(?!\n)/g, "] ")

        // 9. Same for parentheses
        .replace(/\s*\)/g, ")")
        .replace(/\(\s*/g, "(")

        // 10. Add legitimate spacing
        .replace(/\](?=[^\s.,;!?\]])/g, "] ")
        .replace(/(?<=[^\s\[])\[/g, " [")

        // 11. Fix double spaces
        .replace(/[ \t]{2,}/g, " ")
        // 12. Ensure max 2 newlines
        .replace(/\n{3,}/g, "\n\n")
        .trim();

    return text;
}

export async function fixAllBrackets(workspaceId: string): Promise<{ fixed: number, total: number }> {

    const chapters = await db.chapters
        .where('workspaceId')
        .equals(workspaceId)
        .and(c => c.status === 'translated' && !!c.content_translated)
        .toArray();

    let fixed = 0;

    for (const chapter of chapters) {
        const originalContent = chapter.content_translated!;
        const originalTitle = chapter.title_translated || "";

        const cleanedContent = normalizeVietnameseContent(originalContent);
        const cleanedTitle = originalTitle ? normalizeVietnameseContent(originalTitle) : originalTitle;

        // FORCE UPDATE: Always update to ensure normalization is applied

        await db.chapters.update(chapter.id!, {
            content_translated: cleanedContent,
            title_translated: cleanedTitle
        });
    }

    return { fixed, total: chapters.length };
}

/**
 * conflict-resolver.ts
 * Purpose: ULTRA STRICT - Only keep the best entities.
 */

import { semanticScoreEntity } from './semantic-score';

export enum EntityFinalDecision {
    KEEP = 'keep',
    DOWNGRADE = 'downgrade',
    REJECT = 'reject'
}

export interface ResolverResult {
    decision: EntityFinalDecision;
    score: number;
    reasons: string[];
}

export function resolveEntity(input: {
    text: string;
    frequency: number;
    patternMatched: boolean;
    semanticFlags: any;
}): ResolverResult {

    if (!input.patternMatched) {
        return { decision: EntityFinalDecision.REJECT, score: 0, reasons: ['no_pattern'] };
    }

    const result = semanticScoreEntity({
        text: input.text,
        frequency: input.frequency,
        flags: input.semanticFlags
    });

    const score = result.score;

    // --- ULTRA STRICT GATE (v4.5) ---
    // Goal: Only keep ~500-1000 high-quality entities, reject 95%+

    // 1. Score < 60 = instant reject
    if (score < 60) {
        return { decision: EntityFinalDecision.REJECT, score, reasons: [...result.reasons, 'score_too_low'] };
    }

    // 2. Score 60-69 needs HIGH frequency
    if (score < 70 && input.frequency < 30) {
        return { decision: EntityFinalDecision.REJECT, score, reasons: [...result.reasons, 'weak_and_rare'] };
    }

    // 3. Score >= 70 OR freq >= 100 = KEEP
    if (score >= 70 || input.frequency >= 100) {
        return { decision: EntityFinalDecision.KEEP, score, reasons: result.reasons };
    }

    // 4. Medium confidence = DOWNGRADE (for review)
    return { decision: EntityFinalDecision.DOWNGRADE, score, reasons: result.reasons };
}

/**
 * Forensic JSON Export Formats
 * Generates 3 different JSON formats for different use cases
 */

import type { HeuristicTerm } from '@/lib/db';

export type ExportFormat = 'raw' | 'forensic' | 'summary';

interface DropReason {
    reason: string;
    count: number;
    percentage: number;
    examples: string[];
}

interface RawDropJSON {
    type: string;
    total_scanned: number;
    total_kept: number;
    total_dropped: number;
    drop_reasons: DropReason[];
}

interface ForensicAnalysisItem {
    drop_reason: string;
    classification: 'INTENTIONAL' | 'QUESTIONABLE' | 'DANGEROUS';
    technical_cause: string[];
    impact_if_fix: {
        precision: string;
        recall: string;
        performance: string;
        risk: string;
    };
    conceptual_fix: string[];
    recommendation: string;
}

interface ForensicAnalysisJSON {
    type: string;
    analysis: ForensicAnalysisItem[];
}

interface SummaryJSON {
    type: string;
    summary: {
        top_problem: string;
        top_problem_percentage: number;
        risk_level: 'LOW' | 'MEDIUM' | 'HIGH';
        suggested_action: string;
    };
}

/**
 * Generate RAW DROP JSON format
 */
export function generateRawDropJSON(terms: HeuristicTerm[], type: string): RawDropJSON {
    const kept = terms.filter(t => t.isApproved);
    const dropped = terms.filter(t => !t.isApproved);

    // Analyze drop reasons
    const reasonMap = new Map<string, string[]>();

    dropped.forEach(term => {
        const reason = inferDropReason(term);
        const existing = reasonMap.get(reason) || [];
        if (existing.length < 5) {
            existing.push(term.original);
        }
        reasonMap.set(reason, existing);
    });

    const drop_reasons: DropReason[] = Array.from(reasonMap.entries()).map(([reason, examples]) => ({
        reason,
        count: dropped.filter(t => inferDropReason(t) === reason).length,
        percentage: dropped.length > 0 ? (dropped.filter(t => inferDropReason(t) === reason).length / dropped.length) * 100 : 0,
        examples
    })).sort((a, b) => b.count - a.count);

    return {
        type,
        total_scanned: terms.length,
        total_kept: kept.length,
        total_dropped: dropped.length,
        drop_reasons
    };
}

/**
 * Generate FORENSIC ANALYSIS JSON format
 */
export function generateForensicJSON(terms: HeuristicTerm[], type: string): ForensicAnalysisJSON {
    const dropped = terms.filter(t => !t.isApproved);

    // Group by drop reason
    const reasonMap = new Map<string, HeuristicTerm[]>();
    dropped.forEach(term => {
        const reason = inferDropReason(term);
        const existing = reasonMap.get(reason) || [];
        existing.push(term);
        reasonMap.set(reason, existing);
    });

    const analysis: ForensicAnalysisItem[] = Array.from(reasonMap.entries()).map(([reason, terms]) => {
        const classification = classifyDropReason(reason, type);
        const technicalCause = getTechnicalCause(reason, type);
        const impact = getImpactAssessment(reason, type);
        const conceptualFix = getConceptualFix(reason, type);
        const recommendation = getRecommendation(classification, impact);

        return {
            drop_reason: reason,
            classification,
            technical_cause: technicalCause,
            impact_if_fix: impact,
            conceptual_fix: conceptualFix,
            recommendation
        };
    }).sort((a, b) => {
        // Sort: QUESTIONABLE first, then DANGEROUS, then INTENTIONAL
        const order = { QUESTIONABLE: 0, DANGEROUS: 1, INTENTIONAL: 2 };
        return order[a.classification] - order[b.classification];
    });

    return { type, analysis };
}

/**
 * Generate SUMMARY JSON format
 */
export function generateSummaryJSON(terms: HeuristicTerm[], type: string): SummaryJSON {
    const dropped = terms.filter(t => !t.isApproved);

    // Find top problem
    const reasonMap = new Map<string, number>();
    dropped.forEach(term => {
        const reason = inferDropReason(term);
        reasonMap.set(reason, (reasonMap.get(reason) || 0) + 1);
    });

    const topProblem = Array.from(reasonMap.entries())
        .sort((a, b) => b[1] - a[1])[0];

    const topProblemPercentage = dropped.length > 0 ? (topProblem[1] / dropped.length) * 100 : 0;
    const riskLevel = getRiskLevel(topProblem[0], topProblemPercentage);
    const suggestedAction = getSuggestedAction(topProblem[0], type);

    return {
        type,
        summary: {
            top_problem: topProblem[0],
            top_problem_percentage: topProblemPercentage,
            risk_level: riskLevel,
            suggested_action: suggestedAction
        }
    };
}

/**
 * Helper: Infer drop reason
 */
function inferDropReason(term: HeuristicTerm): string {
    const { original, occurrences = 0 } = term;

    if (occurrences < 2) return 'LOW_FREQUENCY';
    if (original.length === 1) return 'TOO_SHORT';
    if (original.length > 6) return 'TOO_LONG';

    // Type-specific
    if (term.type === 'skill' && !hasSkillSuffix(original)) return 'MISSING_SKILL_SUFFIX';
    if (term.type === 'character') return 'NO_ANCHOR';
    if (term.type === 'location' && !hasLocationSuffix(original)) return 'MISSING_LOCATION_SUFFIX';

    return 'OTHER';
}

/**
 * Helper: Classify drop reason
 */
function classifyDropReason(reason: string, type: string): 'INTENTIONAL' | 'QUESTIONABLE' | 'DANGEROUS' {
    if (reason === 'LOW_FREQUENCY') return 'INTENTIONAL';
    if (reason === 'TOO_SHORT') return 'INTENTIONAL';
    if (reason === 'TOO_LONG') return 'QUESTIONABLE';
    if (reason === 'NO_ANCHOR') return 'QUESTIONABLE';
    if (reason === 'MISSING_SKILL_SUFFIX') return 'QUESTIONABLE';
    if (reason === 'MISSING_LOCATION_SUFFIX') return 'QUESTIONABLE';
    return 'QUESTIONABLE';
}

/**
 * Helper: Get technical cause
 */
function getTechnicalCause(reason: string, type: string): string[] {
    const causes: Record<string, string[]> = {
        NO_ANCHOR: [
            'Pattern yêu cầu anchor hoặc verb',
            'Standalone name không match',
            'Thiếu context xung quanh'
        ],
        MISSING_SKILL_SUFFIX: [
            'Pattern chỉ match khi có suffix cụ thể',
            'Nhiều skill không theo format chuẩn'
        ],
        MISSING_LOCATION_SUFFIX: [
            'Pattern yêu cầu suffix địa danh',
            'Tên địa điểm không theo quy ước'
        ],
        TOO_LONG: [
            'Regex có giới hạn độ dài',
            'Có thể bắt nhầm cụm từ thay vì entity'
        ],
        LOW_FREQUENCY: [
            'Ngưỡng tần suất tối thiểu là 2',
            'Xuất hiện 1 lần có thể là typo'
        ]
    };
    return causes[reason] || ['Cần phân tích thủ công'];
}

/**
 * Helper: Get impact assessment
 */
function getImpactAssessment(reason: string, type: string) {
    const impacts: Record<string, any> = {
        NO_ANCHOR: {
            precision: '-10~15%',
            recall: '+30~40%',
            performance: 'No impact',
            risk: 'Medium'
        },
        MISSING_SKILL_SUFFIX: {
            precision: '-5~10%',
            recall: '+20~30%',
            performance: 'No impact',
            risk: 'Low'
        },
        MISSING_LOCATION_SUFFIX: {
            precision: '-5~10%',
            recall: '+15~25%',
            performance: 'No impact',
            risk: 'Low'
        },
        TOO_LONG: {
            precision: '+5~10%',
            recall: '-10~15%',
            performance: 'No impact',
            risk: 'Low'
        }
    };
    return impacts[reason] || {
        precision: 'Unknown',
        recall: 'Unknown',
        performance: 'Unknown',
        risk: 'Unknown'
    };
}

/**
 * Helper: Get conceptual fix
 */
function getConceptualFix(reason: string, type: string): string[] {
    const fixes: Record<string, string[]> = {
        NO_ANCHOR: [
            'Soft opt-in với context check',
            'Anchor relaxation có điều kiện',
            'Thêm whitelist cho tên phổ biến'
        ],
        MISSING_SKILL_SUFFIX: [
            'Suffix expansion',
            'Pattern refinement cho skill không chuẩn'
        ],
        MISSING_LOCATION_SUFFIX: [
            'Suffix expansion',
            'Thêm pattern cho địa danh đặc biệt'
        ],
        TOO_LONG: [
            'Tăng max length có điều kiện',
            'Thêm context check để tránh false positive'
        ]
    };
    return fixes[reason] || ['Cần phân tích thủ công'];
}

/**
 * Helper: Get recommendation
 */
function getRecommendation(classification: string, impact: any): string {
    if (classification === 'INTENTIONAL') return 'Không cần sửa - Đúng thiết kế';
    if (classification === 'DANGEROUS') return 'KHÔNG NÊN sửa - Rủi ro cao';
    if (impact.risk === 'High') return 'QUESTIONABLE - Cần test kỹ trước khi apply';
    if (impact.risk === 'Medium') return 'QUESTIONABLE - Test precision trước khi apply';
    return 'QUESTIONABLE - Có thể thử nghiệm';
}

/**
 * Helper: Get risk level
 */
function getRiskLevel(reason: string, percentage: number): 'LOW' | 'MEDIUM' | 'HIGH' {
    if (percentage > 70) return 'HIGH';
    if (percentage > 40) return 'MEDIUM';
    return 'LOW';
}

/**
 * Helper: Get suggested action
 */
function getSuggestedAction(reason: string, type: string): string {
    const actions: Record<string, string> = {
        NO_ANCHOR: 'Anchor relaxation',
        MISSING_SKILL_SUFFIX: 'Suffix expansion',
        MISSING_LOCATION_SUFFIX: 'Suffix expansion',
        TOO_LONG: 'Max length adjustment',
        LOW_FREQUENCY: 'Không cần action'
    };
    return actions[reason] || 'Manual review';
}

/**
 * Helper: Check skill suffix
 */
function hasSkillSuffix(term: string): boolean {
    const suffixes = ['功', '诀', '法', '步', '术', '拳', '掌', '剑', '阵', '经', '典', '指', '印', '击', '斩', '破', '杀', '爆', '轰', '裂', '灭', '封', '镇', '禁'];
    return suffixes.some(s => term.endsWith(s));
}

/**
 * Helper: Check location suffix
 */
function hasLocationSuffix(term: string): boolean {
    const suffixes = ['山', '河', '湖', '海', '城', '镇', '村', '府', '宫', '殿', '阁', '楼', '院', '谷', '峰', '岛', '洲', '国', '郡', '州', '县'];
    return suffixes.some(s => term.endsWith(s));
}

import { db } from '../../db';
import { withKeyRotation } from '../client';
import { DEFAULT_MODEL } from '../../ai-models';
import { SyllableRepository } from '../../repositories/syllable-repo';

/**
 * AI HEURISTIC TERMS REFINER v3.1 (The Hybrid Engine)
 * Purpose: Use AI only for classification and filtering. Use LOCAL dictionary for 100% Han-Viet translation.
 */
export async function refineHeuristicTerms(workspaceId: string, onLog?: (msg: string) => void) {
    const modelSetting = await db.settings.get("aiModel");
    const aiModel = (modelSetting?.value as string) || DEFAULT_MODEL;

    const totalTerms = await db.heuristicTerms
        .where('workspaceId')
        .equals(workspaceId)
        .and(t => !t.isApproved && !t.isGarbage)
        .toArray();

    if (totalTerms.length === 0) {
        if (onLog) onLog("✨ Không có thuật ngữ mới cần AI thẩm định.");
        return;
    }

    // Prepare Local Dictionary (v2.9)
    if (onLog) onLog("🔋 Đang nạp bộ từ điển Hán-Việt... (Dùng 100% nội bộ)");
    const repo = SyllableRepository.getInstance();
    await repo.load("/dicts/ChinesePhienAmWords.txt");

    const CHUNK_SIZE = 100;
    const totalChunks = Math.ceil(totalTerms.length / CHUNK_SIZE);

    if (onLog) onLog(`📡 Đã tìm thấy ${totalTerms.length} từ. Chia làm ${totalChunks} đợt phân loại...`);

    // --- LEARN FROM BLACKLIST (v3.0) ---
    const blacklist = await db.blacklist
        .where('[workspaceId+source]')
        .equals([workspaceId, 'heuristic'])
        .toArray();
    const blacklistExamples = blacklist.slice(-20).map(b => b.word).join(', ');
    const learnSection = blacklistExamples
        ? `\nVí dụ rác NHẬN DIỆN RIÊNG cho Workspace này (Người dùng đã xoá):\n[${blacklistExamples}]`
        : "";

    if (onLog && blacklist.length > 0) onLog(`🧠 AI đang học từ ${blacklist.length} rác anh đã xoá...`);

    let totalInputTokens = 0;
    let totalOutputTokens = 0;

    for (let i = 0; i < totalChunks; i++) {
        const start = i * CHUNK_SIZE;
        const end = start + CHUNK_SIZE;
        const chunk = totalTerms.slice(start, end);

        if (onLog) onLog(`⚙️ Đang phân loại đợt ${i + 1}/${totalChunks} (${chunk.length} từ)...`);

        const termList = chunk.map(t => `${t.original} (${t.type})`).join('\n');

        const systemInstruction = `
Lọc từ điển truyện (v3.1 - Extreme Noise Filter).
Mục tiêu: PHÂN LOẠI thực thể (Tên người/Chiêu thức/Địa danh) và TIÊU DIỆT rác ngữ pháp.
${learnSection}

QUY TẮC THANH TRỪNG CỰC ĐOAN (XÓA 100%):
1. Grammar Particles: Hiện tại, Thực tại, Tự kỷ/Tự mình, Phát hiện, Cảm giác, Thành công, Bình thường, Đồng thời, Thật ra, Hóa ra, Sau đó.
2. Pronouns: Hắn, Nàng, Hai người, Bọn họ...
3. Verbs: Nhận vi, Thấy, Quyết định, Chuẩn bị, Bắt đầu...
4. Status: Vô cùng, Rất, Đặc biệt, Nhất thời, Đột nhiên.

CHỈ PHÂN LOẠI - TUYỆT ĐỐI KHÔNG DỊCH:
- character: Tên người.
- skill: Công pháp, chiêu thức.
- location: Địa danh.

YÊU CẦU: Trả về JSON mảng: [{"original": "...", "type": "character | skill | location"}]
`;

        try {
            const rawResult = await withKeyRotation<{
                candidates: { content: { parts: { text: string }[] } }[],
                usageMetadata?: { promptTokenCount: number, candidatesTokenCount: number }
            }>(
                {
                    model: aiModel,
                    systemInstruction,
                    prompt: `Hãy phân loại và loại rác danh sách sau:\n${termList}`,
                    generationConfig: {
                        temperature: 0.1,
                        maxOutputTokens: 8192,
                    }
                }
            );

            const { recordUsage } = await import('../client');
            if (rawResult.usageMetadata) {
                recordUsage(aiModel, rawResult.usageMetadata);
                totalInputTokens += rawResult.usageMetadata.promptTokenCount;
                totalOutputTokens += rawResult.usageMetadata.candidatesTokenCount;
            }

            const rawText = rawResult.candidates[0].content.parts[0].text;
            let refined: { original: string, type: string }[] = [];

            try {
                const cleanText = rawText.replace(/```json|```/g, "").trim();
                const jsonMatch = cleanText.match(/\[[\s\S]*\]/);
                const jsonStr = jsonMatch ? jsonMatch[0] : cleanText;

                try {
                    refined = JSON.parse(jsonStr);
                } catch (parseErr: unknown) {
                    const lastBrace = jsonStr.lastIndexOf('}');
                    if (lastBrace !== -1) {
                        const repaired = jsonStr.substring(0, lastBrace + 1) + "]";
                        refined = JSON.parse(repaired);
                    } else {
                        throw parseErr;
                    }
                }
            } catch {
                if (onLog) onLog(`⚠️ Đợt ${i + 1} phản hồi lỗi định dạng, đang bỏ qua...`);
                continue;
            }

            let updateCount = 0;
            const validOriginals = new Set(refined.map(r => r.original));
            const chunkOriginals = chunk.map(t => t.original);
            const garbageOriginals = chunkOriginals.filter(o => !validOriginals.has(o));

            if (garbageOriginals.length > 0) {
                await db.heuristicTerms
                    .where('workspaceId').equals(workspaceId)
                    .and(t => garbageOriginals.includes(t.original))
                    .modify({ isGarbage: true, updatedAt: new Date() });
            }

            for (const item of refined) {
                const existing = chunk.find(t => t.original === item.original);
                if (existing) {
                    const normalizedType = item.type?.toLowerCase();
                    const finalType = ['character', 'skill', 'location'].includes(normalizedType) ? normalizedType : 'unknown';
                    const localTranslated = repo.toHanViet(item.original);

                    await db.heuristicTerms.update(existing.id!, {
                        translated: localTranslated,
                        type: finalType as any,
                        confidence: 99,
                        updatedAt: new Date()
                    });
                    updateCount++;
                }
            }

            if (onLog) onLog(`✅ Xong đợt ${i + 1}. Giữ ${updateCount}, dọn ${garbageOriginals.length} rác.`);
        } catch (error: unknown) {
            console.error(`Error in chunk ${i}:`, error);
            if (onLog) onLog(`⚠️ Đợt ${i + 1} gặp lỗi API.`);
        }
    }

    if (onLog) {
        onLog(`📊 TỔNG KẾT: Đã sử dụng ${totalInputTokens} input / ${totalOutputTokens} output tokens.`);
        onLog(`✨ HOÀN TẤT. Đã dùng bộ phiên âm nội bộ để dịch 100% thuật ngữ.`);
    }
}

/**
 * semantic-score.ts
 * Purpose: ULTRA STRICT scoring with heavy function word penalties.
 */

export interface SemanticScoreResult {
    score: number;
    reasons: string[];
}

const BASE_SCORE = 30;

const BONUS = {
    lengthGood: 10,
    rareChar: 15,
    actionContext: 10,
    cleanCandidate: 15,
    tierCompound: 20,
};

const PENALTY = {
    genericTerm: -20,
    functionWord: -80,      // Increased from -50
    determiner: -80,        // Increased from -50
    tooLong: -30,
    composite: -40,
    abstractTrap: -25,
    startsWithJunk: -90,    // NEW: Starts with function word
};

// Expanded function words
const FUNCTION_WORDS = ['已经', '曾经', '有人', '没有', '一位', '位', '他', '她', '的', '了', '在', '和', '与'];

export function semanticScoreEntity(input: {
    text: string;
    frequency: number;
    flags: Record<string, boolean>;
}): SemanticScoreResult {

    let score = BASE_SCORE;
    const reasons: string[] = [];

    // 1. INSTANT KILL for junk starters
    if (input.flags.isFunctionWord || input.flags.isBlacklisted) {
        score += PENALTY.startsWithJunk;
        reasons.push('starts_with_junk');
    }

    // 2. Length
    if (input.text.length > 6) {
        score += PENALTY.tooLong;
        reasons.push('too_long');
    } else if (input.text.length >= 2 && input.text.length <= 4) {
        score += BONUS.lengthGood;
        reasons.push('good_length');
    }

    // 3. Rare chars
    if (/[尸王宗阁技阵经诀殿宫神圣府院寺]/.test(input.text)) {
        score += BONUS.rareChar;
        reasons.push('rare_char');
    }

    // 4. Fatal penalties
    if (input.flags.isFunctionWord || input.flags.isBlacklisted) {
        score += PENALTY.functionWord;
        reasons.push('blacklisted');
    }

    if (input.flags.isComposite) {
        score += PENALTY.composite;
        reasons.push('composite');
    }

    // 5. Positive signals
    if (input.flags.hasVerbContext) {
        score += BONUS.actionContext;
        reasons.push('verb_context');
    }

    if (!input.flags.isFunctionWord && !input.flags.isBlacklisted) {
        score += BONUS.cleanCandidate;
        reasons.push('clean');
    }

    // 6. Frequency boost (capped)
    if (input.frequency >= 100) {
        score += 20;
        reasons.push('very_frequent');
    } else if (input.frequency >= 50) {
        score += 10;
        reasons.push('frequent');
    }

    // 7. STRICT CAP (0-100)
    score = Math.max(0, Math.min(100, score));

    return { score, reasons };
}

import { CorrectionEntry } from "../../db";

/**
 * Correction Engine Module
 * Responsible for applying dictionary rules, corrections, and pattern matching.
 */

export function repairSentenceStructure(text: string): string {
    if (!text) return "";

    const pronouns = "Hắn|Nó|Gã|Mụ|Lão|Người|Kẻ|Cô|Anh|Chị|Ông|Bà|Tên|Con|Thằng|Bọn|Lũ|Các|Những|Mọi|Mỗi|Một";
    const conjunctions = "Nhưng|Và|Thì|Mà|Bởi|Tuy|Nên|Rồi|Đã|Đang|Sẽ|Tại|Vì|Nếu|Do|Để|Với|Cùng";
    const prepositions = "Trong|Ngoài|Trên|Dưới|Trước|Sau|Lúc|Khi|Giờ";
    const verbs = "Thở|Ngước|Nhìn|Thấy|Nghe|Nói|Bảo|Hỏi|Đáp|Cười|Khóc|Đứng|Ngồi|Đi|Chạy|Đến|Về";
    const others = "Cái|Cố|Vị|Đích|Chỉ|Có|Không|Chưa|Chẳng|Biết|Nhớ|Quên|Muốn|Thích|Yêu|Ghét";

    const safeWords = `${pronouns}|${conjunctions}|${prepositions}|${verbs}|${others}`;
    const regex = new RegExp(`, (${safeWords})`, 'g');

    return text.replace(regex, '. $1');
}

export async function generateCacheKey(
    text: string,
    model: string,
    instruction: string,
    _glossaryContext: string = "" // Keep for signature compatibility but ignore in hash
): Promise<string> {
    // AUDIT FIX: We exclude glossaryContext from the cache key.
    // Why? Glossary recommendations might vary slightly between batches,
    // but we don't want to re-translate the same paragraph just because 
    // one minor term was added/removed from the prompt's reference list.
    const data = `${text}|${model}|${instruction}`;
    const encoder = new TextEncoder();
    const hashBuffer = await crypto.subtle.digest('SHA-256', encoder.encode(data));
    const hashArray = Array.from(new Uint8Array(hashBuffer));
    return hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
}

export function escapeRegExp(string: string): string {
    return string.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

export function applyAllCorrections(text: string, rules: Partial<CorrectionEntry>[]): string {
    if (!text || !rules || rules.length === 0) return text;

    let result = text.normalize('NFC')
        .replace(/[\u200B-\u200D\uFEFF]/g, '')
        .replace(/[\u00A0\u1680\u180e\u2000-\u200a\u202f\u205f\u3000]/g, ' ')
        .replace(/[ \t]+/g, ' ');

    const replaces = rules.filter(r => (r.type === 'replace' || !r.type) && (r.from || r.original));
    const wraps = rules.filter(r => r.type === 'wrap' && r.target && r.open && r.close);
    const regexes = rules.filter(r => r.type === 'regex' && (r.pattern || r.original));

    if (replaces.length > 0) {
        const sorted = [...replaces].sort((a, b) => {
            const lenA = (a.from || a.original || "").length;
            const lenB = (b.from || b.original || "").length;
            return lenB - lenA;
        });

        const replacementMap = new Map(sorted.map(r => {
            const from = (r.from || r.original || "").trim().normalize('NFC').replace(/\s+/g, ' ').toLowerCase();
            const to = (r.to ?? r.replacement ?? "").normalize('NFC');
            return [from, to];
        }));

        const pattern = new RegExp(
            sorted
                .map(r => {
                    const cleanFrom = (r.from || r.original || "").trim().normalize('NFC').replace(/\s+/g, ' ');
                    return escapeRegExp(cleanFrom);
                })
                .filter(p => p.length > 0)
                .join('|'),
            'gi'
        );

        if (pattern.source !== "(?:)" && pattern.source !== "") {
            result = result.replace(pattern, (match) => {
                const to = replacementMap.get(match.toLowerCase());
                if (to === undefined) return match;

                if (match === match.toUpperCase() && match !== match.toLowerCase()) return to.toUpperCase();
                if (match.length > 0 && match[0] === match[0].toUpperCase() && match[0] !== match[0].toLowerCase()) {
                    return to.charAt(0).toUpperCase() + to.slice(1);
                }
                return to;
            });
        }
    }

    for (const rule of wraps) {
        result = safeWrap(result, rule.target!.normalize('NFC'), rule.open!, rule.close!);
    }

    for (const rule of regexes) {
        try {
            const p = rule.pattern || rule.original;
            const r = rule.replace || rule.replacement || "";
            if (p) {
                result = result.replace(new RegExp(p, 'gi'), r);
            }
        } catch (e) {
            console.error("Regex correction failed:", e, rule);
        }
    }

    return result;
}

export function applyCorrectionRule(text: string, rule: Partial<CorrectionEntry>): string {
    return applyAllCorrections(text, [rule]);
}

export function safeReplace(text: string, from: string, to: string) {
    return applyAllCorrections(text, [{ type: 'replace', from, to }]);
}

export function safeWrap(text: string, target: string, open: string, close: string) {
    if (!target || !open || !close) return text;
    const escaped = escapeRegExp(target.normalize('NFC'));
    const regex = new RegExp(escaped, 'gi');

    return text.replace(regex, (match, offset, full) => {
        const before = full[offset - 1];
        const after = full[offset + match.length];
        if (before === open && after === close) return match;
        return `${open}${match}${close}`;
    });
}

import { db } from "../db";
import { withKeyRotation } from "./client";
import { DEFAULT_MODEL } from "../ai-models";
import { SyllableRepository } from "../repositories/syllable-repo";
import { VietPhraseRepository } from "../repositories/viet-phrase-repo";
import { extractResponseText, scrubAIChatter } from "./contentProcessor";

/**
 * Detect if a title contains Chinese characters
 * Uses a broad range of CJK characters for maximum safety
 */
export function hasChinese(text: string): boolean {
    if (!text) return false;
    // Common Han (U+4E00-U+9FFF) + Ext A (U+3400-U+4DBF) + Compatibility (U+F900-U+FAFF)
    // Extended to cover Ext B-G (U+20000-U+2EBEF) via surrogate pairs
    return /[\u4e00-\u9fff\u3400-\u4dbf\uf900-\ufaff]|[\ud840-\ud87f][\udc00-\udfff]/.test(text);
}

/**
 * Nuclear Rescue: Forces conversion to VietPhrase/Hán Việt to ensure 100% Latin
 */
async function forceRescue(text: string): Promise<string> {
    console.log(`[Title Fixer] ☢️ Nuclear Rescue triggered for: "${text}"`);
    const vpRepo = VietPhraseRepository.getInstance();
    const sylRepo = SyllableRepository.getInstance();

    // Ensure dicts are loaded
    await Promise.all([
        sylRepo.load("/dicts/ChinesePhienAmWords.txt"),
        vpRepo.load("/dicts/VietPhrase.txt")
    ]);

    // Step 1: Broad VietPhrase conversion (handles common terms and names)
    let translated = vpRepo.convert(text);

    // Step 2: Individual Han character fallback (Hán Việt)
    // Use traditional Unicode ranges for Webpack compatibility
    const hanRegex = /[\u4e00-\u9fff\u3400-\u4dbf\uf900-\ufaff]|[\ud840-\ud87f][\udc00-\udfff]/g;

    translated = translated.replace(hanRegex, (char) => {
        const hv = sylRepo.get(char);
        if (hv) return " " + hv.charAt(0).toUpperCase() + hv.slice(1) + " ";
        return ""; // Completely remove unknown Han chars to ensure "No Chinese" rule
    });

    const finalResult = translated.replace(/\s+/g, ' ').trim();
    console.log(`[Title Fixer] ✅ Nuclear Rescue result: "${finalResult}"`);
    return finalResult || "Tiêu đề không rõ"; // Fallback if result is somehow empty
}

/**
 * Translate ONLY the chapter title (ultra-cheap, ~$0.000005/title)
 */
export async function translateTitleOnly(chineseTitle: string, retryCount = 0): Promise<string> {
    const modelSetting = await db.settings.get("aiModel");
    const aiModel = (modelSetting?.value || DEFAULT_MODEL) as string;

    const prompt = `[QUY TẮC TIÊU ĐỀ - BẮT BUỘC]
Bạn là chuyên gia dịch thuật và Hán Việt.
Nhiệm vụ: Dịch tiêu đề chương này sang Tiếng Việt.

Tiêu đề gốc: "${chineseTitle}"

QUY TẮC:
1. CHỈ TRẢ VỀ DUY NHẤT TIÊU ĐỀ TIẾNG VIỆT.
2. TUYỆT ĐỐI KHÔNG ĐƯỢC GIỮ LẠI BẤT KỲ CHỮ HÁN NÀO.
3. Nếu không biết dịch, hãy phiên âm Hán Việt.

VÍ DỤ ĐÚNG: "Chương 2: Thuận Thế"`;

    try {
        const result = (await withKeyRotation<any>(
            {
                model: aiModel.trim(),
                prompt,
                generationConfig: {
                    temperature: 0.1,
                    maxOutputTokens: 100,
                }
            },
            (msg: string) => console.log(`[Title Fixer] ${msg}`)
        ));

        let text = extractResponseText(result);
        text = scrubAIChatter(text).trim().replace(/^"|"$/g, '');

        if (hasChinese(text)) {
            if (retryCount < 1) {
                return translateTitleOnly(chineseTitle, retryCount + 1);
            } else {
                return await forceRescue(text || chineseTitle);
            }
        }

        return text;
    } catch (error) {
        console.error(`[Title Fixer] error:`, error);
        if (hasChinese(chineseTitle)) return await forceRescue(chineseTitle);
        return chineseTitle; // Return original if it somehow has no Chinese but failed AI
    }
}

/**
 * Fix all chapter titles in a workspace
 */
export async function fixAllTitles(
    workspaceId: string,
    onProgress?: (current: number, total: number, title: string) => void
): Promise<{ fixed: number; skipped: number; errors: string[] }> {

    const chapters = await db.chapters
        .where('workspaceId')
        .equals(workspaceId)
        .toArray();

    // Fix those where either raw title OR translated title has Chinese
    // IMPORTANT: Only fix chapters that have been translated/reviewing or already have a title_translated field.
    // This prevents translating titles for chapters that the user hasn't translated the content for yet.
    const needFix = chapters.filter(ch =>
        (ch.status === 'translated' || ch.status === 'reviewing' || !!ch.title_translated) &&
        hasChinese(ch.title_translated || ch.title)
    );
    const stats = { fixed: 0, skipped: 0, errors: [] as string[] };

    for (let i = 0; i < needFix.length; i++) {
        const chapter = needFix[i];
        const originalTitle = chapter.title_translated || chapter.title;

        try {
            onProgress?.(i + 1, needFix.length, originalTitle);

            const newTitle = await translateTitleOnly(originalTitle);

            if (!newTitle || hasChinese(newTitle)) {
                // If it STILL has Chinese even after forceRescue, something is very wrong with the regexes
                stats.errors.push(`Chương ${chapter.order}: Thất bại khi diệt chữ Hân (Sau cứu hộ)`);
                stats.skipped++;
                continue;
            }

            await db.chapters.update(chapter.id!, { title_translated: newTitle });
            stats.fixed++;

            // Minimal throttle
            await new Promise(r => setTimeout(r, 50));
        } catch (error: any) {
            stats.errors.push(`Chương ${chapter.order}: ${error.message || 'Lỗi không xác định'}`);
            stats.skipped++;
        }
    }

    return stats;
}

import { db, DictionaryEntry } from "../db";
import { DEFAULT_MODEL } from "../ai-models";
import { TranslationResult, TranslationLog } from "./types";
import { withKeyRotation, recordUsage } from "./client";
import { extractResponseText } from "./contentProcessor";
import { analyzeTextHeuristics, assembleSystemInstruction } from "./rules/assembler";
import { withAdaptiveTokens } from "./adaptive-tokens";
import { buildGlossary } from "./translation/glossary-builder";
import { parsePlainTextChapter } from "./translation/parser";
import { applyPostProcessing } from "./translation/post-processor";
import { calculateStats } from "./translation/stats-calculator";

/**
 * Main Translation Function (Orchestrator)
 * 
 * Architecture:
 * - Modular design with clear separation of concerns
 * - Adaptive token management for cost optimization
 * - Smart retry logic for reliability
 * 
 * Flow:
 * 1. Build glossary context
 * 2. Analyze text heuristics
 * 3. Call API with adaptive tokens
 * 4. Parse response
 * 5. Post-process (corrections, validation)
 * 6. Calculate stats
 */
export const translateChapter = async (
    workspaceId: string,
    text: string,
    onLog: (log: TranslationLog) => void,
    onSuccess: (result: TranslationResult) => void,
    customInstruction?: string,
    sharedGlossary?: DictionaryEntry[],
    enableThinking?: boolean,  // 🧠 For Gemini 2.5 Flash
    thinkingLevel?: "minimal" | "low" | "medium" | "high",  // 🧠 For Gemini 3.0 Flash
) => {
    const modelSetting = await db.settings.get("aiModel");
    const aiModel = modelSetting?.value || DEFAULT_MODEL;

    /**
     * Build thinking config based on model version
     * Gemini 2.5: Uses thinkingBudget (-1 = dynamic, 0 = disabled)
     * Gemini 3.0: Uses thinking_level ("minimal" | "low" | "medium" | "high")
     */
    const buildThinkingConfig = (
        model: string,
        legacyEnableThinking?: boolean,
        level?: "minimal" | "low" | "medium" | "high"
    ): { thinkingBudget?: number; thinking_level?: string } => {
        const isGemini3 = model.includes('gemini-3');

        if (isGemini3) {
            // Gemini 3.0: Use thinking_level
            return {
                thinking_level: level || "minimal"  // Default to minimal to save cost
            };
        } else {
            // Gemini 2.5: Use thinkingBudget
            return {
                thinkingBudget: legacyEnableThinking ? -1 : 0
            };
        }
    };


    // Clean text: Normalize Unicode (NFC) and remove excessive whitespace
    text = text.normalize('NFC').trim().replace(/\n\s*\n/g, '\n\n');

    try {
        // 1. Build Glossary Context
        onLog({
            timestamp: new Date(),
            message: '📚 Đang tải từ điển...',
            type: 'info'
        });
        const { relevantDict, glossaryContext } = await buildGlossary(
            workspaceId,
            text,
            sharedGlossary
        );

        // 2. Analyze Text Heuristics
        const analysis = analyzeTextHeuristics(text);
        onLog({
            timestamp: new Date(),
            message: `🧠 Phân tích ngữ cảnh: ${analysis.detectedRegister} | Confidence: ${analysis.confidence}% | Combat: ${analysis.isCombat ? 'Có' : 'Không'}`,
            type: 'info'
        });

        // 3. Build System Instruction
        const fullInstruction = assembleSystemInstruction(analysis, glossaryContext, customInstruction, text);
        onLog({
            timestamp: new Date(),
            message: '🤖 Đang gửi yêu cầu đến AI...',
            type: 'info'
        });

        // 4. Call API with Adaptive Tokens (Smart Retry)
        const adaptiveResult = await withAdaptiveTokens(
            async (maxTokens: number) => {
                console.log(`📡 [PAYLOAD] Model: ${aiModel} | Content Size: ${text.length} chars | System Instruction Size: ${fullInstruction.length} chars | Dynamic maxTokens: ${maxTokens}`);

                return await withKeyRotation<Record<string, unknown>>(
                    {
                        model: (aiModel as string).trim(),
                        systemInstruction: fullInstruction,
                        prompt: text,
                        generationConfig: {
                            temperature: 0.1,
                            topP: 0.95,
                            maxOutputTokens: maxTokens,
                            responseMimeType: "text/plain",
                            thinkingConfig: buildThinkingConfig(aiModel as string, enableThinking, thinkingLevel)
                        }
                    },
                    (msg: string) => {
                        onLog({ timestamp: new Date(), message: msg, type: 'info' });
                    }
                );
            },
            (result) => {
                const candidates = (result as { candidates?: Array<{ finishReason?: string }> }).candidates;
                return candidates?.[0]?.finishReason;
            },
            {
                inputLength: text.length,  // Content length only (for output estimation)
                baseBuffer: 3500,  // Gemini 2.5 Flash thinking tokens (observed: 1858-3108, avg ~2500)
                minTokens: 2048,
                maxTokens: 16384   // Gemini 2.5 Flash supports up to 65K, but 16K is practical limit
            }
        );

        // Warn if chapter is too long for non-chunking
        if (text.length > 5000) {
            onLog({
                timestamp: new Date(),
                message: `⚠️ Chapter dài ${text.length} chars - Khuyến nghị bật Chunking để tránh lỗi MAX_TOKENS`,
                type: 'info'
            });
        }

        const rawResult = adaptiveResult.data;



        // Track retry for final message (don't toast immediately)
        const wasRetried = adaptiveResult.wasRetried;

        // Track usage
        if (rawResult.usageMetadata) {
            const metadata = rawResult.usageMetadata as any;
            const thinkingTokens = metadata.thoughtsTokenCount || 0;
            const inputTokens = metadata.promptTokenCount || 0;
            const outputTokens = metadata.candidatesTokenCount || 0;

            console.log(`🧠 [THINKING TOKENS] Input: ${inputTokens} | Output: ${outputTokens} | Thinking: ${thinkingTokens} | Total: ${inputTokens + outputTokens + thinkingTokens}`);

            recordUsage(aiModel as string, rawResult.usageMetadata);
        }

        // 5. Extract & Validate Response
        const rawText = extractResponseText(rawResult).trim();

        if (!rawText || rawText.trim() === "") {
            const finishReason = adaptiveResult.finishReason;
            if (finishReason === "MAX_TOKENS") {
                throw new Error(`❌ Chapter quá dài (${text.length} chars) - Output bị cắt do MAX_TOKENS! Hãy BẬT CHUNKING trong cấu hình dịch.`);
            }
            throw new Error(`❌ AI trả về nội dung rỗng! Finish reason: ${finishReason}. Có thể do: API lỗi, Prompt bị reject, hoặc Content vi phạm policy.`);
        }

        // 6. Parse Plain Text Response
        const parsed = parsePlainTextChapter(rawText);

        // 7. Post-Process (Corrections, Validation, Final Sweep)
        const processed = await applyPostProcessing(parsed, workspaceId, relevantDict);

        // 8. Calculate Stats
        const stats = calculateStats(
            processed.translatedText,
            relevantDict,
            rawResult.usageMetadata as { promptTokenCount?: number; candidatesTokenCount?: number }
        );

        const result: TranslationResult = {
            ...processed,
            stats
        };

        // 9. Success - Consolidated message with all info
        const tokenMsg = stats.tokens
            ? ` [${stats.tokens.input}i + ${stats.tokens.output}o = ${stats.tokens.total}t]`
            : "";
        const retrySuffix = wasRetried ? " (retry)" : "";
        onLog({
            timestamp: new Date(),
            message: `✅ Dịch xong!${tokenMsg}${retrySuffix}`,
            type: 'success'
        });
        onSuccess(result);

    } catch (error: unknown) {
        const message = error instanceof Error ? error.message : String(error);
        onLog({ timestamp: new Date(), message: `Lỗi: ${message}`, type: 'error' });
        throw error;
    }
};

import { db } from "./db";
import { invoke } from "@tauri-apps/api/core";
import { listen } from "@tauri-apps/api/event";
import { open } from "@tauri-apps/plugin-shell";

const DRIVE_API_URL = "https://www.googleapis.com/drive/v3";
const DRIVE_UPLOAD_URL = "https://www.googleapis.com/upload/drive/v3";

interface GoogleDriveConfig {
    clientId: string;
    scopes: string;
}

export class GoogleDriveService {
    private static instance: GoogleDriveService;
    private accessToken: string | null = null;
    private expiresAt: number = 0;
    private clientId: string | null = null; // Store for lazy init

    private constructor() { }

    static getInstance() {
        if (!GoogleDriveService.instance) {
            GoogleDriveService.instance = new GoogleDriveService();
        }
        return GoogleDriveService.instance;
    }

    isReady() {
        return !!this.clientId; // Always "ready" if we have a client ID now
    }

    async init(clientId: string) {
        if (typeof window === "undefined") return;
        this.clientId = clientId;
    }

    async getAccessToken(): Promise<string> {
        if (this.accessToken && Date.now() < this.expiresAt) {
            return this.accessToken;
        }

        const savedToken = await db.settings.get("gdrive_token");
        if (savedToken?.value) {
            this.accessToken = savedToken.value as string;
            return this.accessToken!;
        }

        throw new Error("Mất kết nối với Google Drive. Hãy kết nối lại.");
    }

    async connect() {
        if (!this.clientId) {
            const clientIdSetting = await db.settings.get("gdrive_client_id");
            if (clientIdSetting?.value) {
                this.clientId = clientIdSetting.value as string;
            }
        }

        if (!this.clientId) {
            throw new Error("Chưa cấu hình Client ID.");
        }

        // 1. Start local server in Rust
        const { port, state } = await invoke<{ port: number, state: string }>("start_auth_server");
        // Use localhost if port 3000 (standard Web App), else 127.0.0.1 (Loopback/Desktop)
        const redirectUri = port === 3000 ? `http://localhost:3000` : `http://127.0.0.1:${port}`;

        // 2. Construct OAuth URL with State protection
        const scope = encodeURIComponent("https://www.googleapis.com/auth/drive.file https://www.googleapis.com/auth/drive.metadata.readonly https://www.googleapis.com/auth/userinfo.email");
        const authUrl = `https://accounts.google.com/o/oauth2/v2/auth?client_id=${this.clientId}&redirect_uri=${redirectUri}&response_type=token&scope=${scope}&state=${state}`;

        // 3. Open system browser
        await open(authUrl);

        // 4. Listen for token event
        return new Promise<void>((resolve, reject) => {
            const timeout = setTimeout(() => {
                if (unlisten) unlisten();
                reject(new Error("Hết thời gian chờ đăng nhập (120s). Bạn hãy đảm bảo đã nhấn 'Cho phép' trên trình duyệt và đã thêm URI vào Google Console."));
            }, 120000);

            let unlisten: () => void;
            listen<string>("oauth_token_received", async (event) => {
                clearTimeout(timeout);
                const hash = event.payload;

                // Parse hash
                const params = new URLSearchParams(hash.substring(1));
                const token = params.get("access_token");
                const expiresIn = params.get("expires_in");

                if (token) {
                    this.accessToken = token as string;
                    this.expiresAt = Date.now() + (parseInt(expiresIn || "3600") * 1000);

                    await db.settings.put({ key: "gdrive_token", value: this.accessToken });

                    try {
                        const userInfo = await this.getUserInfo(this.accessToken);
                        await db.settings.put({ key: "gdrive_user", value: userInfo });
                    } catch (e) {
                        // Silently fail user info fetch
                    }

                    resolve();
                } else {
                    reject(new Error("Không tìm thấy token trong phản hồi."));
                }

                if (unlisten) unlisten();
            }).then(u => unlisten = u);
        });
    }

    async listFolders(parentId: string = "root") {
        const token = await this.getAccessToken();
        const q = `'${parentId}' in parents and mimeType = 'application/vnd.google-apps.folder' and trashed = false`;
        const resp = await fetch(`${DRIVE_API_URL}/files?q=${encodeURIComponent(q)}&fields=files(id, name)`, {
            headers: { Authorization: `Bearer ${token}` }
        });

        if (!resp.ok) {
            const errData = await resp.json().catch(() => ({}));
            if (resp.status === 401) {
                // Token expired, clear it
                this.accessToken = null;
                await db.settings.delete("gdrive_token");
                throw new Error("Phiên làm việc hết hạn. Vui lòng kết nối lại Google Drive.");
            }
            throw new Error(`Lỗi khi tải danh sách thư mục (${resp.status})`);
        }
        const data = await resp.json();
        return data.files as { id: string; name: string }[];
    }

    async createFolder(name: string, parentId: string = "root") {
        const token = await this.getAccessToken();
        const resp = await fetch(`${DRIVE_API_URL}/files`, {
            method: "POST",
            headers: {
                Authorization: `Bearer ${token}`,
                "Content-Type": "application/json"
            },
            body: JSON.stringify({
                name,
                mimeType: "application/vnd.google-apps.folder",
                parents: [parentId]
            })
        });

        if (!resp.ok) {
            const errData = await resp.json().catch(() => ({}));
            if (resp.status === 401) {
                this.accessToken = null;
                await db.settings.delete("gdrive_token");
                throw new Error("Phiên làm việc hết hạn. Vui lòng kết nối lại Google Drive.");
            }
            throw new Error(`Lỗi khi tạo thư mục (${resp.status})`);
        }
        const data = await resp.json();
        return data as { id: string; name: string };
    }

    async uploadFile(blob: Blob, filename: string, folderId: string = "root") {
        const token = await this.getAccessToken();

        // Multipart upload for metadata + media
        const metadata = {
            name: filename,
            parents: [folderId]
        };

        const formData = new FormData();
        formData.append("metadata", new Blob([JSON.stringify(metadata)], { type: "application/json" }));
        formData.append("file", blob);

        const resp = await fetch(`${DRIVE_UPLOAD_URL}/files?uploadType=multipart`, {
            method: "POST",
            headers: {
                Authorization: `Bearer ${token}`
            },
            body: formData
        });

        if (!resp.ok) {
            const errData = await resp.json().catch(() => ({}));
            if (resp.status === 401) {
                this.accessToken = null;
                await db.settings.delete("gdrive_token");
                throw new Error("Phiên làm việc hết hạn. Vui lòng kết nối lại Google Drive.");
            }
            throw new Error(errData.error?.message || `Lỗi khi tải file lên Drive (${resp.status})`);
        }

        return await resp.json();
    }

    async getUserInfo(token: string) {
        const resp = await fetch(`https://www.googleapis.com/oauth2/v3/userinfo`, {
            headers: { Authorization: `Bearer ${token}` }
        });
        if (!resp.ok) throw new Error("Không thể lấy thông tin người dùng");
        return await resp.json();
    }

    async logout() {
        if ((window as any).google?.accounts?.oauth2?.revoke && this.accessToken) {
            (window as any).google.accounts.oauth2.revoke(this.accessToken, () => {
                // Token revoked silently
            });
        }
        this.accessToken = null;
        this.expiresAt = 0;
        await db.settings.delete("gdrive_token");
        await db.settings.delete("gdrive_user");
    }
}

