export function getTextHash(text: string): string {
    let hash = 0;
    for (let i = 0; i < text.length; i++) {
        const char = text.charCodeAt(i);
        hash = ((hash << 5) - hash) + char;
        hash |= 0; // Convert to 32bit integer
    }
    return hash.toString();
}

export async function speak(
    chapterId: number,
    text: string,
    voice: string = "vi-VN-HoaiMyNeural",
    pitch: string = "+0Hz",
    rate: string = "+0%"
): Promise<string> {
    // Validation / Fallback
    if (!pitch || pitch === 'undefined' || pitch === 'undefinedHz') pitch = "+0Hz";
    if (!rate || rate === 'undefined' || rate === 'undefined%') rate = "+0%";

    const textHash = getTextHash(text);

    // Safety check: ensure all query parameters are defined and valid for compound index
    if (chapterId === undefined || !voice || !textHash || pitch === undefined || rate === undefined) {
        // Skip cache check if parameters are invalid
    } else {
        // 1. Check Cache using explicit compound index for performance and stability
        try {
            const cache = await db.ttsCache
                .where('[chapterId+voice+textHash+pitch+rate]')
                .equals([chapterId, voice, textHash, pitch, rate])
                .first();

            if (cache) {
                const blob = new Blob([new Uint8Array(cache.blob)], { type: 'audio/mpeg' });
                return URL.createObjectURL(blob);
            }
        } catch (err) {
            // Fallback: search without compound index if it fails
            const fallback = await db.ttsCache.where({ chapterId, textHash, voice }).first();
            if (fallback) {
                const blob = new Blob([new Uint8Array(fallback.blob)], { type: 'audio/mpeg' });
                return URL.createObjectURL(blob);
            }
        }
    }

    // 2. Fetch from Backend
    const audioData = await invoke<number[]>("edge_tts_speak", { text, voice, pitch, rate });
    const uint8Array = new Uint8Array(audioData);

    // 3. Save to Cache (Async)
    db.ttsCache.add({
        chapterId,
        voice,
        textHash,
        pitch,
        rate,
        blob: uint8Array.buffer,
        createdAt: new Date()
    }).catch(() => { /* Silently fail cache write */ });

    const blob = new Blob([uint8Array], { type: 'audio/mpeg' });
    return URL.createObjectURL(blob);
}

export async function prefetchTTS(chapterId: number, text: string, voice: string, pitch: string = "+0Hz", rate: string = "+0%") {
    const textHash = getTextHash(text);

    if (chapterId === undefined || !voice || !textHash || pitch === undefined || rate === undefined) return;

    try {
        const count = await db.ttsCache
            .where('[chapterId+voice+textHash+pitch+rate]')
            .equals([chapterId, voice, textHash, pitch, rate])
            .count();
        if (count > 0) return; // Already cached
    } catch (e) {
        // Fallback or ignore
    }

    // Generate in background
    speak(chapterId, text, voice, pitch, rate).then(url => {
        URL.revokeObjectURL(url);
    }).catch(() => { /* Silently fail prefetch */ });
}

// Shared TypeScript type definitions for the AI Translator app

import { Chapter, DictionaryEntry } from "./db";

/**
 * Character extracted from glossary
 */
export interface GlossaryCharacter {
    id?: number;
    original: string;
    translated: string;
    type: 'name';
    gender?: 'male' | 'female' | 'unknown';
    role?: 'main' | 'support' | 'villain' | 'mob' | string;
    description?: string;
    isExisting?: boolean;
    status?: 'save' | 'blacklist' | 'ignore'; // For review dialog
}

/**
 * Term extracted from glossary
 */
export interface GlossaryTerm {
    id?: number;
    original: string;
    translated: string;
    type: 'term' | 'phrase' | 'general' | 'item' | 'location' | 'skill' | 'organization' | 'other' | string;
    description?: string;
    isExisting?: boolean;
    status?: 'save' | 'blacklist' | 'ignore'; // For review dialog
}

/**
 * Result from AI glossary extraction
 */
export interface GlossaryResult {
    characters: GlossaryCharacter[];
    terms: GlossaryTerm[];
}

/**
 * Translation configuration
 */
export interface TranslationConfig {
    model: string;
    temperature?: number;
    maxTokens?: number;
    customPrompt?: string;
}

/**
 * Translation settings from database
 */
export interface TranslationSettings {
    apiKey: string;
    model: string;
    temperature?: number;
    customPrompt?: string;
}

/**
 * Batch translation options
 */
export interface BatchTranslateOptions {
    chapters: Chapter[];
    config: TranslationConfig;
    settings: TranslationSettings;
    onProgress?: (current: number, total: number, status: string) => void;
    onReviewNeeded?: (chars: GlossaryCharacter[], terms: GlossaryTerm[]) => void;
}

/**
 * Inspection issue found in chapter
 */
export interface InspectionIssue {
    type: 'bracket' | 'quote' | 'punctuation' | 'spacing' | 'untranslated' | 'pronoun' | 'grammar' | 'spelling' | 'other';
    severity: 'error' | 'warning' | 'info';
    message: string;
    original?: string;
    suggestion?: string;
    reason?: string;
    position?: number;
}

/**
 * Review data for glossary extraction
 */
export interface ReviewData {
    chars: GlossaryCharacter[];
    terms: GlossaryTerm[];
}

/**
 * Extended Chapter type with additional properties
 */
export interface ExtendedChapter extends Chapter {
    // Add any additional properties that aren't in the base Chapter type
}

/**
 * Log callback function type
 */
export type LogCallback = (message: string) => void;

/**
 * Error with message property
 */
export interface ErrorWithMessage {
    message: string;
}

/**
 * Type guard to check if error has message
 */
export function isErrorWithMessage(error: unknown): error is ErrorWithMessage {
    return (
        typeof error === 'object' &&
        error !== null &&
        'message' in error &&
        typeof (error as Record<string, unknown>).message === 'string'
    );
}

/**
 * Get error message from unknown error
 */
export function getErrorMessage(error: unknown): string {
    if (isErrorWithMessage(error)) return error.message;
    return String(error);
}
